UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites arithmétiques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites arithmétiques : raison, terme général $u_n = u_0 + nr$, somme par Gauss $S = (n+1)(u_0 + u_n)/2$.","exercices":[{"number":1,"title_fr":"Identifier et calculer","points":5,"preamble_fr":"On considère la suite $(u_n)$ telle que $u_0 = 3$ et $u_{n+1} = u_n + 5$.","questions":[{"number":1,"stem_fr":"Justifier que $(u_n)$ est arithmétique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Par définition d''une suite arithmétique : $u_{n+1} - u_n = r$ constant. Ici $u_{n+1} - u_n = (u_n + 5) - u_n = 5$."},{"text_fr":"La différence entre deux termes consécutifs est **constante et vaut 5**. Donc $(u_n)$ est arithmétique de **raison $r = 5$**."}],"final_answer_fr":"$r = 5$"}},{"number":2,"stem_fr":"Donner l''expression de $u_n$ en fonction de $n$.","points":1,"solution":{"steps":[{"text_fr":"**Terme général** : $u_n = u_0 + nr = 3 + 5n$."}],"final_answer_fr":"$u_n = 3 + 5n$"}},{"number":3,"stem_fr":"Calculer $u_{10}$, $u_{20}$ et $u_{50}$.","points":2,"solution":{"steps":[{"text_fr":"Application directe : $u_{10} = 3 + 50 = 53$."},{"text_fr":"$u_{20} = 3 + 100 = 103$ ; $u_{50} = 3 + 250 = 253$.","tip_fr":"L''expression explicite permet de calculer n''importe quel terme directement, sans énumérer les précédents."}],"final_answer_fr":"$u_{10} = 53$, $u_{20} = 103$, $u_{50} = 253$"}}]},{"number":2,"title_fr":"Sommes","points":5,"preamble_fr":"On utilise la suite $(u_n)$ de l''Exercice 1.","questions":[{"number":1,"stem_fr":"Calculer la somme $S = u_0 + u_1 + \\dots + u_{10}$ (11 termes).","points":3,"solution":{"steps":[{"text_fr":"**Formule de Gauss** : $S = (\\text{nombre de termes}) \\times \\dfrac{\\text{premier} + \\text{dernier}}{2}$."},{"text_fr":"Ici 11 termes, $u_0 = 3$, $u_{10} = 53$. Donc $S = 11 \\times (3 + 53)/2 = 11 \\times 28 = 308$."}],"final_answer_fr":"$S = 308$"}},{"number":2,"stem_fr":"Calculer $1 + 2 + 3 + \\dots + 100$.","points":2,"solution":{"steps":[{"text_fr":"Suite arithmétique de premier terme 1, raison 1, 100 termes."},{"text_fr":"**Formule** : $S_{100} = 100 \\times (1 + 100)/2 = 5050$. Anecdote : Gauss l''aurait calculée à l''âge de 9 ans, à la surprise de son instituteur."}],"final_answer_fr":"$S = 5050$"}}]},{"number":3,"title_fr":"Sens de variation","points":5,"preamble_fr":"Soit $(v_n)$ arithmétique de premier terme $v_0 = 100$ et raison $r = -3$.","questions":[{"number":1,"stem_fr":"Donner l''expression de $v_n$ et étudier le sens de variation.","points":3,"solution":{"steps":[{"text_fr":"$v_n = 100 - 3n$. Calcul : $v_{n+1} - v_n = -3 < 0$. La suite est **strictement décroissante**."},{"text_fr":"**Règle générale** : suite arithmétique avec $r > 0$ → croissante ; $r < 0$ → décroissante ; $r = 0$ → constante."}],"final_answer_fr":"$v_n = 100 - 3n$, décroissante"}},{"number":2,"stem_fr":"À partir de quel rang $n$ a-t-on $v_n < 0$ ?","points":2,"solution":{"steps":[{"text_fr":"$v_n < 0 \\iff 100 - 3n < 0 \\iff n > 100/3 \\approx 33{,}3$."},{"text_fr":"Donc à partir de $n = 34$ : $v_{34} = 100 - 102 = -2 < 0$ ✓. Avant : $v_{33} = 100 - 99 = 1 > 0$."}],"final_answer_fr":"$n \\ge 34$"}}]},{"number":4,"title_fr":"Problème — escaliers","points":5,"preamble_fr":"Un escalier comporte 50 marches. La première marche a une hauteur de 18 cm. Chaque marche suivante est 0,2 cm plus haute que la précédente.","questions":[{"number":1,"stem_fr":"Quelle est la hauteur de la 25ème marche ?","points":2,"solution":{"steps":[{"text_fr":"Suite arithmétique de $u_1 = 18$, $r = 0{,}2$. Terme général : $u_n = u_1 + (n-1) r = 18 + 0{,}2(n-1)$."},{"text_fr":"Pour la 25ème marche : $u_{25} = 18 + 0{,}2 \\times 24 = 18 + 4{,}8 = 22{,}8\\,cm$."}],"final_answer_fr":"$u_{25} = 22{,}8$ cm"}},{"number":2,"stem_fr":"Quelle est la hauteur totale de l''escalier ?","points":3,"solution":{"steps":[{"text_fr":"Hauteur totale = somme de toutes les hauteurs. $u_{50} = 18 + 0{,}2 \\times 49 = 27{,}8\\,cm$."},{"text_fr":"Somme : $H = 50 \\times (18 + 27{,}8)/2 = 50 \\times 22{,}9 = 1145\\,cm = 11{,}45\\,m$."},{"text_fr":"Vérification : si toutes les marches faisaient 22,9 cm (la moyenne), la hauteur serait $50 \\times 22{,}9 = 1145\\,cm$ ✓."}],"final_answer_fr":"$H = 11{,}45$ m"}}]}]}'::jsonb WHERE code = 'arithmetic_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites géométriques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites géométriques : raison $q$, terme général $u_n = u_0 q^n$, somme $S = u_0 (1 - q^{n+1})/(1-q)$, limites selon $|q|$.","exercices":[{"number":1,"title_fr":"Identification","points":5,"preamble_fr":"Soit $(u_n)$ telle que $u_0 = 2$ et $u_{n+1} = 3 u_n$.","questions":[{"number":1,"stem_fr":"Montrer que $(u_n)$ est géométrique et donner la raison.","points":2,"solution":{"steps":[{"text_fr":"Définition d''une suite géométrique : $u_{n+1}/u_n = q$ constant. Ici $u_{n+1}/u_n = 3$."},{"text_fr":"Donc $(u_n)$ est géométrique de **raison $q = 3$** (multiplication par 3 à chaque étape)."}],"final_answer_fr":"$q = 3$"}},{"number":2,"stem_fr":"Donner $u_n$ en fonction de $n$ et calculer $u_5$, $u_{10}$.","points":3,"solution":{"steps":[{"text_fr":"Terme général : $u_n = u_0 q^n = 2 \\cdot 3^n$."},{"text_fr":"$u_5 = 2 \\times 243 = 486$ ; $u_{10} = 2 \\times 59049 = 118098$.","tip_fr":"Croissance exponentielle pour $|q| > 1$ — chaque terme est $q$ fois le précédent."}],"final_answer_fr":"$u_n = 2 \\cdot 3^n$, $u_5 = 486$, $u_{10} = 118098$"}}]},{"number":2,"title_fr":"Sommes","points":5,"preamble_fr":"Avec la suite $u_n = 2 \\cdot 3^n$.","questions":[{"number":1,"stem_fr":"Calculer $S = u_0 + u_1 + \\dots + u_5$ (6 termes).","points":3,"solution":{"steps":[{"text_fr":"**Formule** : $S = u_0 \\dfrac{1 - q^{n+1}}{1 - q}$ pour $n+1$ termes."},{"text_fr":"Ici 6 termes, $u_0 = 2$, $q = 3$. $S = 2 \\dfrac{1 - 3^6}{1 - 3} = 2 \\dfrac{1 - 729}{-2} = 2 \\times 364 = 728$."}],"final_answer_fr":"$S = 728$"}},{"number":2,"stem_fr":"Limite de la somme infinie $1 + 1/2 + 1/4 + 1/8 + \\dots$","points":2,"solution":{"steps":[{"text_fr":"Suite géométrique $u_0 = 1$, $q = 1/2$, $|q| < 1$ → somme infinie converge."},{"text_fr":"Formule : $S_\\infty = u_0/(1 - q) = 1/(1 - 1/2) = 2$.","tip_fr":"Pour $|q| < 1$, $q^n \\to 0$ et $S_n \\to u_0/(1-q)$ — c''est le paradoxe de Zénon résolu."}],"final_answer_fr":"$S_\\infty = 2$"}}]},{"number":3,"title_fr":"Comportement à l''infini","points":5,"preamble_fr":"Étudier la limite de la suite $(u_n)$ selon la valeur de $q$ pour $u_n = u_0 q^n$ avec $u_0 > 0$.","questions":[{"number":1,"stem_fr":"Donner la limite $\\lim u_n$ selon les 4 cas : $q > 1$, $q = 1$, $|q| < 1$, $q \\le -1$.","points":5,"solution":{"steps":[{"text_fr":"**$q > 1$** : $q^n \\to +\\infty$, donc $u_n \\to +\\infty$. Croissance exponentielle."},{"text_fr":"**$q = 1$** : $u_n = u_0$ constant. Limite : $u_0$."},{"text_fr":"**$|q| < 1$** (c-à-d $-1 < q < 1$) : $q^n \\to 0$, donc $u_n \\to 0$. Décroissance vers 0."},{"text_fr":"**$q = -1$** : $u_n$ alterne $\\pm u_0$ → **pas de limite**."},{"text_fr":"**$q < -1$** : oscillations divergentes ($|u_n| \\to +\\infty$ avec alternance de signe) → **pas de limite**.","tip_fr":"Mémo : la limite d''une suite géométrique dépend uniquement de la position de $q$ par rapport à 1 et -1."}]}}]},{"number":4,"title_fr":"Application — capital à intérêts composés","points":5,"preamble_fr":"Un capital $C_0 = 1000\\,€$ est placé à un taux annuel de 5%. Soit $C_n$ le capital après $n$ ans.","questions":[{"number":1,"stem_fr":"Justifier que $(C_n)$ est géométrique. Donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Chaque année, le capital est multiplié par $1{,}05$ (capital initial + 5% d''intérêts). Donc $C_{n+1} = 1{,}05 \\times C_n$."},{"text_fr":"Géométrique de raison $q = 1{,}05$."}],"final_answer_fr":"$q = 1{,}05$"}},{"number":2,"stem_fr":"Calculer $C_{10}$ et $C_{30}$.","points":2,"solution":{"steps":[{"text_fr":"$C_n = C_0 \\times 1{,}05^n = 1000 \\times 1{,}05^n$."},{"text_fr":"$C_{10} = 1000 \\times 1{,}629 \\approx 1629\\,€$ ; $C_{30} = 1000 \\times 4{,}322 \\approx 4322\\,€$."},{"text_fr":"**Insight** : en 30 ans à 5%, le capital plus que quadruple. C''est le pouvoir des intérêts composés (vs intérêts simples qui donneraient 1000 + 30×50 = 2500 €)."}],"final_answer_fr":"$C_{10} \\approx 1629$ €, $C_{30} \\approx 4322$ €"}},{"number":3,"stem_fr":"Après combien d''années le capital aura-t-il doublé ?","points":1,"solution":{"steps":[{"text_fr":"Résoudre $1{,}05^n = 2 \\iff n = \\ln 2/\\ln 1{,}05 \\approx 0{,}693/0{,}0488 \\approx 14{,}2\\,\\text{ans}$."},{"text_fr":"Donc le capital double en environ **14 ans** au taux de 5%. Règle approximative : ''doublement = 72/taux %'' (ici 72/5 = 14,4, très proche).","tip_fr":"La ''règle de 72'' est très utilisée en finance : à taux r% par an, doublement en ~72/r années."}],"final_answer_fr":"$n \\approx 14$ ans"}}]}]}'::jsonb WHERE code = 'geometric_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Convergence des suites","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Convergence, limite, théorème des gendarmes, monotonie + bornes, opérations sur les limites.","exercices":[{"number":1,"title_fr":"Limites usuelles","points":5,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{n \\to \\infty} 1/n$, $1/n^2$, $1/\\sqrt{n}$.","points":2,"solution":{"steps":[{"text_fr":"**Règle générale** : pour tout $\\alpha > 0$, $\\lim 1/n^\\alpha = 0$."},{"text_fr":"Application : les 3 limites valent **0**. Plus $\\alpha$ est grand, plus la décroissance est rapide."}],"final_answer_fr":"Toutes valent 0"}},{"number":2,"stem_fr":"$\\lim_{n \\to \\infty} \\dfrac{2n + 1}{n + 3}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty/\\infty$. Diviser haut et bas par $n$ : $\\dfrac{2 + 1/n}{1 + 3/n} \\to \\dfrac{2}{1} = 2$."},{"text_fr":"**Règle** : pour un quotient de polynômes de même degré, limite = rapport des coefficients dominants."}],"final_answer_fr":"$\\lim = 2$"}},{"number":3,"stem_fr":"$\\lim_{n \\to \\infty} \\sqrt{n+1} - \\sqrt{n}$.","points":1,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. **Astuce de la quantité conjuguée** : multiplier par $(\\sqrt{n+1} + \\sqrt{n})/(\\sqrt{n+1} + \\sqrt{n})$."},{"text_fr":"$\\sqrt{n+1} - \\sqrt{n} = \\dfrac{(n+1) - n}{\\sqrt{n+1} + \\sqrt{n}} = \\dfrac{1}{\\sqrt{n+1} + \\sqrt{n}} \\to 0$."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":2,"title_fr":"Théorème des gendarmes","points":5,"preamble_fr":"Soit $u_n = \\dfrac{\\sin(n)}{n}$ pour $n \\ge 1$.","questions":[{"number":1,"stem_fr":"Encadrer $u_n$.","points":2,"solution":{"steps":[{"text_fr":"$-1 \\le \\sin(n) \\le 1$. Diviser par $n > 0$ : $-1/n \\le \\sin(n)/n \\le 1/n$."}],"final_answer_fr":"$-1/n \\le u_n \\le 1/n$"}},{"number":2,"stem_fr":"En déduire la limite.","points":3,"solution":{"steps":[{"text_fr":"$\\lim -1/n = 0$ et $\\lim 1/n = 0$."},{"text_fr":"Par le **théorème des gendarmes**, $u_n$ est encadrée par deux suites qui tendent toutes deux vers 0, donc $\\lim u_n = 0$.","tip_fr":"Note : $\\sin(n)$ n''a PAS de limite, mais $\\sin(n)/n$ converge grâce à la décroissance de $1/n$."}],"final_answer_fr":"$\\lim u_n = 0$"}}]},{"number":3,"title_fr":"Convergence par monotonie","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 1$ et $u_{n+1} = \\sqrt{2 + u_n}$.","questions":[{"number":1,"stem_fr":"Étude de $(u_n)$.","points":4,"subparts":[{"letter":"a","stem_fr":"Montrer par récurrence que $1 \\le u_n \\le 2$.","points":2,"solution":{"steps":[{"text_fr":"**Initialisation** : $u_0 = 1$ vérifie $1 \\le 1 \\le 2$ ✓."},{"text_fr":"**Hérédité** : si $1 \\le u_n \\le 2$, alors $3 \\le 2 + u_n \\le 4$, donc $\\sqrt 3 \\le \\sqrt{2 + u_n} \\le 2$. Comme $\\sqrt 3 > 1$ : $1 \\le u_{n+1} \\le 2$ ✓."},{"text_fr":"Conclusion : pour tout $n$, $1 \\le u_n \\le 2$. La suite est **bornée**."}]}},{"letter":"b","stem_fr":"Montrer que $(u_n)$ est croissante.","points":2,"solution":{"steps":[{"text_fr":"On veut $u_{n+1} \\ge u_n$, soit $\\sqrt{2 + u_n} \\ge u_n$. Élever au carré (tous positifs) : $2 + u_n \\ge u_n^2 \\iff u_n^2 - u_n - 2 \\le 0 \\iff (u_n - 2)(u_n + 1) \\le 0$."},{"text_fr":"Sur $[1, 2]$ : $u_n - 2 \\le 0$ et $u_n + 1 > 0$ → produit $\\le 0$ ✓. Donc $u_{n+1} \\ge u_n$ : croissante."}]}}]},{"number":2,"stem_fr":"En déduire que $(u_n)$ converge. Calculer sa limite.","points":1,"solution":{"steps":[{"text_fr":"Suite croissante et majorée (par 2) → **convergente** par théorème de la limite monotone."},{"text_fr":"Limite $L$ : passage à la limite dans $u_{n+1} = \\sqrt{2 + u_n}$ donne $L = \\sqrt{2 + L}$. Carré : $L^2 = L + 2 \\iff (L-2)(L+1) = 0$. Avec $L \\in [1, 2]$ : $L = 2$."}],"final_answer_fr":"$L = 2$"}}]},{"number":4,"title_fr":"Opérations sur les limites","points":5,"preamble_fr":"Soient $u_n = (n^2 + 1)/n$ et $v_n = (3n - 1)/(n + 2)$. Calculer $\\lim u_n$, $\\lim v_n$, $\\lim u_n + v_n$, $\\lim u_n v_n$.","questions":[{"number":1,"stem_fr":"Calculer chaque limite.","points":5,"solution":{"steps":[{"text_fr":"$u_n = n + 1/n \\to +\\infty$."},{"text_fr":"$v_n = (3n - 1)/(n + 2) \\to 3$ (mêmes degrés, rapport des dominants)."},{"text_fr":"**Somme** : $\\lim (u_n + v_n) = +\\infty + 3 = +\\infty$."},{"text_fr":"**Produit** : $\\lim (u_n v_n) = +\\infty \\times 3 = +\\infty$.","tip_fr":"Opérations sur les limites : (+\\infty) + fini = +\\infty ; (+\\infty) × fini > 0 = +\\infty ; (+\\infty) × 0 ou (+\\infty) - (+\\infty) = formes indéterminées (cas à étudier)."}],"final_answer_fr":"$\\lim u_n = +\\infty$, $\\lim v_n = 3$, somme et produit $= +\\infty$"}}]}]}'::jsonb WHERE code = 'seq_convergence';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites récurrentes","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites définies par récurrence $u_{n+1} = f(u_n)$, point fixe, étude de la convergence par monotonie + bornes.","exercices":[{"number":1,"title_fr":"Récurrence simple","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 0$ et $u_{n+1} = (u_n + 4)/2$.","questions":[{"number":1,"stem_fr":"Calculer $u_1, u_2, u_3$ et conjecturer la limite.","points":2,"solution":{"steps":[{"text_fr":"$u_1 = (0 + 4)/2 = 2$. $u_2 = (2 + 4)/2 = 3$. $u_3 = (3 + 4)/2 = 3{,}5$."},{"text_fr":"La suite semble croître vers une limite proche de **4** : 0, 2, 3, 3.5, 3.75, ..."}],"final_answer_fr":"Conjecture : $L = 4$"}},{"number":2,"stem_fr":"Trouver le point fixe de $f(x) = (x+4)/2$.","points":2,"solution":{"steps":[{"text_fr":"**Point fixe** : $L = f(L) \\iff L = (L+4)/2 \\iff 2L = L + 4 \\iff L = 4$. ✓ avec la conjecture."},{"text_fr":"Mais attention : trouver le point fixe ne prouve pas la convergence — il faut aussi vérifier que la suite y tend.","tip_fr":"Le point fixe est un candidat-limite. Pour conclure, il faut montrer monotonie + bornes (théorème de la limite monotone)."}],"final_answer_fr":"$L = 4$"}},{"number":3,"stem_fr":"Montrer que $(u_n)$ est croissante et majorée par 4.","points":1,"solution":{"steps":[{"text_fr":"Par récurrence : si $u_n < 4$, alors $u_{n+1} = (u_n + 4)/2 < (4 + 4)/2 = 4$. Donc $u_n < 4$ pour tout $n$ (majorée)."},{"text_fr":"Croissance : $u_{n+1} - u_n = (u_n + 4)/2 - u_n = (4 - u_n)/2 > 0$ tant que $u_n < 4$. Donc croissante."},{"text_fr":"Croissante + majorée → converge (vers le point fixe $L = 4$)."}]}}]},{"number":2,"title_fr":"Récurrence non linéaire","points":5,"preamble_fr":"Soit $u_0 = 2$ et $u_{n+1} = \\sqrt{u_n + 6}$.","questions":[{"number":1,"stem_fr":"Étude.","points":4,"subparts":[{"letter":"a","stem_fr":"Trouver le point fixe.","points":1,"solution":{"steps":[{"text_fr":"$L = \\sqrt{L + 6} \\Rightarrow L^2 = L + 6 \\Rightarrow L^2 - L - 6 = 0$. Discriminant 25, racines $L = 3$ ou $L = -2$."},{"text_fr":"Comme $\\sqrt{\\cdot} \\ge 0$, la limite (si elle existe) est $\\ge 0$. Donc $L = 3$."}],"final_answer_fr":"$L = 3$"}},{"letter":"b","stem_fr":"Montrer par récurrence que $2 \\le u_n \\le 3$.","points":2,"solution":{"steps":[{"text_fr":"Init : $u_0 = 2$ ✓. Hérédité : si $2 \\le u_n \\le 3$, alors $8 \\le u_n + 6 \\le 9$, donc $\\sqrt{8} \\le u_{n+1} \\le 3$. $\\sqrt 8 \\approx 2{,}83 > 2$ ✓."}]}},{"letter":"c","stem_fr":"Conclure sur la convergence.","points":1,"solution":{"steps":[{"text_fr":"Croissance : $u_{n+1}^2 - u_n^2 = u_n + 6 - u_n^2 = -(u_n - 3)(u_n + 2)$. Sur [2, 3], $(u_n - 3) \\le 0$ et $(u_n + 2) > 0$ → $u_{n+1}^2 \\ge u_n^2$ → $u_{n+1} \\ge u_n$. Croissante + majorée → converge vers L = 3."}]}}]},{"number":2,"stem_fr":"Combien d''itérations sont nécessaires pour atteindre $|u_n - 3| < 10^{-3}$ ?","points":1,"solution":{"steps":[{"text_fr":"Calcul itératif : u_0 = 2 (|err| = 1), u_1 ≈ 2.83 (|err| ≈ 0.17), u_2 ≈ 2.97 (|err| ≈ 0.03), u_3 ≈ 2.995 (|err| ≈ 0.005), u_4 ≈ 2.9992 (|err| ≈ 0.0008)."},{"text_fr":"Donc dès $n = 4$, on a $|u_n - 3| < 10^{-3}$. Convergence rapide."}],"final_answer_fr":"$n = 4$"}}]},{"number":3,"title_fr":"Suite arithmético-géométrique","points":5,"preamble_fr":"Soit $(u_n)$ telle que $u_0 = 0$ et $u_{n+1} = 2 u_n + 3$.","questions":[{"number":1,"stem_fr":"Trouver le point fixe $\\ell$ et étudier $v_n = u_n - \\ell$.","points":3,"solution":{"steps":[{"text_fr":"Point fixe : $\\ell = 2\\ell + 3 \\iff -\\ell = 3 \\iff \\ell = -3$."},{"text_fr":"Posons $v_n = u_n + 3$. Alors $v_{n+1} = u_{n+1} + 3 = 2u_n + 3 + 3 = 2(u_n + 3) = 2 v_n$. $(v_n)$ est **géométrique** de raison 2."},{"text_fr":"$v_0 = u_0 + 3 = 3$. Donc $v_n = 3 \\cdot 2^n$ et $u_n = v_n - 3 = 3 \\cdot 2^n - 3$.","tip_fr":"Astuce arithmético-géométrique : passer à $v_n = u_n - \\ell$ rend la récurrence géométrique pure."}],"final_answer_fr":"$u_n = 3 \\cdot 2^n - 3$"}},{"number":2,"stem_fr":"En déduire $\\lim u_n$.","points":2,"solution":{"steps":[{"text_fr":"Quand $n \\to \\infty$, $2^n \\to +\\infty$, donc $u_n \\to +\\infty$."},{"text_fr":"Note : ici $|q| = 2 > 1$, donc la suite **diverge** vers $+\\infty$. Le point fixe $\\ell = -3$ est **répulsif** (la suite s''en éloigne)."}],"final_answer_fr":"$\\lim u_n = +\\infty$"}}]},{"number":4,"title_fr":"Application — modèle de population","points":5,"preamble_fr":"Une population de bactéries double chaque heure, mais 100 sont prélevées chaque heure pour analyse. À $t = 0$, population = 200.","questions":[{"number":1,"stem_fr":"Modéliser la population $P_n$ après $n$ heures par une suite récurrente.","points":2,"solution":{"steps":[{"text_fr":"$P_0 = 200$. Chaque heure : doublement ($\\times 2$) puis prélèvement (-100). Donc $P_{n+1} = 2 P_n - 100$."}],"final_answer_fr":"$P_{n+1} = 2 P_n - 100$, $P_0 = 200$"}},{"number":2,"stem_fr":"Trouver l''expression explicite de $P_n$ et son comportement.","points":3,"solution":{"steps":[{"text_fr":"Point fixe : $\\ell = 2\\ell - 100 \\iff \\ell = 100$. Posons $Q_n = P_n - 100$. Alors $Q_{n+1} = P_{n+1} - 100 = 2 P_n - 100 - 100 = 2 P_n - 200 = 2(P_n - 100) = 2 Q_n$."},{"text_fr":"$(Q_n)$ géométrique de raison 2, $Q_0 = 100$. Donc $Q_n = 100 \\cdot 2^n$ et $P_n = 100 \\cdot 2^n + 100$."},{"text_fr":"**Vérification** : $P_0 = 100 + 100 = 200$ ✓. $P_1 = 200 + 100 = 300$ ; or $2 P_0 - 100 = 400 - 100 = 300$ ✓."},{"text_fr":"Comportement : la population **explose exponentiellement**. Au bout de 10 heures, $P_{10} = 100 \\cdot 1024 + 100 = 102\\,500$ bactéries."}],"final_answer_fr":"$P_n = 100 (2^n + 1)$, explose"}}]}]}'::jsonb WHERE code = 'seq_recursive';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites adjacentes","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites adjacentes : croissante + décroissante + différence nulle à l''infini → même limite. Outil de démonstration d''existence et d''encadrement.","exercices":[{"number":1,"title_fr":"Définition","points":5,"preamble_fr":"On dit que deux suites $(a_n)$ et $(b_n)$ sont **adjacentes** si $(a_n)$ est croissante, $(b_n)$ est décroissante, et $b_n - a_n \\to 0$.","questions":[{"number":1,"stem_fr":"Énoncer le théorème des suites adjacentes.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : si $(a_n)$ et $(b_n)$ sont adjacentes, alors elles convergent toutes deux vers la **même limite** $\\ell$."},{"text_fr":"De plus, pour tout $n$, $a_n \\le \\ell \\le b_n$. La limite est ainsi **encadrée** par les deux suites."}]}},{"number":2,"stem_fr":"Vérifier que les suites $a_n = 1 - 1/n$ et $b_n = 1 + 1/n$ pour $n \\ge 1$ sont adjacentes.","points":3,"solution":{"steps":[{"text_fr":"Monotonie : $a_{n+1} - a_n = -1/(n+1) - (-1/n) = 1/n - 1/(n+1) > 0$ → croissante ✓."},{"text_fr":"$b_{n+1} - b_n = 1/(n+1) - 1/n < 0$ → décroissante ✓."},{"text_fr":"Différence : $b_n - a_n = 2/n \\to 0$ ✓."},{"text_fr":"Limite commune : 1 (par calcul direct). Encadrement : $a_n \\le 1 \\le b_n$ pour tout $n$ ✓."}],"final_answer_fr":"Adjacentes, limite commune $= 1$"}}]},{"number":2,"title_fr":"Application — encadrement de e","points":5,"preamble_fr":"On considère $a_n = \\sum_{k=0}^{n} \\dfrac{1}{k!}$ et $b_n = a_n + \\dfrac{1}{n \\cdot n!}$.","questions":[{"number":1,"stem_fr":"Montrer que $(a_n)$ est croissante.","points":2,"solution":{"steps":[{"text_fr":"$a_{n+1} - a_n = \\dfrac{1}{(n+1)!} > 0$ → strictement croissante."}]}},{"number":2,"stem_fr":"Admettre que $(b_n)$ est décroissante et que $b_n - a_n \\to 0$. Conclure.","points":3,"solution":{"steps":[{"text_fr":"$(a_n)$ croissante, $(b_n)$ décroissante, $b_n - a_n = 1/(n n!) \\to 0$ → **adjacentes**."},{"text_fr":"Elles convergent vers la même limite $e = \\sum_{k=0}^\\infty 1/k!$ (définition en série de l''exponentielle de Neper)."},{"text_fr":"**Encadrement utile** : $a_n \\le e \\le b_n$. Par exemple $a_5 = 1 + 1 + 1/2 + 1/6 + 1/24 + 1/120 \\approx 2{,}717$ et $b_5 \\approx 2{,}7183$ — encadrement très précis.","tip_fr":"Cette construction est la définition rigoureuse classique de $e$. Elle permet de calculer $e$ avec autant de précision qu''on veut."}],"final_answer_fr":"$\\lim a_n = \\lim b_n = e$"}}]},{"number":3,"title_fr":"Suites construites par récurrence","points":5,"preamble_fr":"Soit $a_0 = 1$, $b_0 = 2$, et pour tout $n$ : $a_{n+1} = \\sqrt{a_n b_n}$ (moyenne géométrique), $b_{n+1} = (a_n + b_n)/2$ (moyenne arithmétique).","questions":[{"number":1,"stem_fr":"Calculer $a_1$ et $b_1$. Conjecturer une relation.","points":2,"solution":{"steps":[{"text_fr":"$a_1 = \\sqrt{1 \\cdot 2} = \\sqrt{2} \\approx 1{,}414$. $b_1 = (1+2)/2 = 1{,}5$."},{"text_fr":"Observation : $a_1 < b_1$. Plus généralement, **AM-GM inequality** : $\\sqrt{ab} \\le (a+b)/2$ avec égalité ssi $a = b$."}],"final_answer_fr":"$a_n \\le b_n$ par AM-GM"}},{"number":2,"stem_fr":"Admettre que $(a_n)$ est croissante et $(b_n)$ décroissante. Si $b_n - a_n \\to 0$, conclure.","points":3,"solution":{"steps":[{"text_fr":"Suites adjacentes — convergent vers la même limite $\\mu$, appelée **moyenne arithmético-géométrique** de $a_0$ et $b_0$."},{"text_fr":"Pour $a_0 = 1, b_0 = 2$ : $\\mu \\approx 1{,}4567$. Cette quantité apparaît dans le calcul d''intégrales elliptiques (méthode de Gauss).","tip_fr":"La moyenne arithmético-géométrique (AGM) converge extrêmement vite — utilisée historiquement pour calculer $\\pi$ avec haute précision (Brent-Salamin)."}],"final_answer_fr":"Convergence vers $\\mu \\approx 1{,}457$"}}]},{"number":4,"title_fr":"Critique du théorème","points":5,"preamble_fr":"Le théorème des suites adjacentes nécessite **3 conditions** ; sans l''une d''elles, la conclusion peut être fausse.","questions":[{"number":1,"stem_fr":"Donner un exemple où $(a_n)$ croissante, $(b_n)$ décroissante, mais $b_n - a_n$ ne tend PAS vers 0. Montrer qu''elles n''ont pas la même limite.","points":3,"solution":{"steps":[{"text_fr":"Exemple : $a_n = 1 - 1/n$ (croissante, limite 1) et $b_n = 2 + 1/n$ (décroissante, limite 2)."},{"text_fr":"Différence : $b_n - a_n = 1 + 2/n \\to 1 \\ne 0$."},{"text_fr":"Limites différentes (1 et 2) → on ne peut pas conclure à une limite commune. Le théorème ne s''applique pas — il faut bien $b_n - a_n \\to 0$."}]}},{"number":2,"stem_fr":"Donner un exemple où $(a_n), (b_n)$ ne sont pas adjacentes mais convergent vers la même limite. Cela contredit-il le théorème ?","points":2,"solution":{"steps":[{"text_fr":"Exemple : $a_n = (-1)^n / n$ et $b_n = 1/n$. Toutes deux tendent vers 0."},{"text_fr":"Mais $(a_n)$ n''est pas monotone (alterne en signe). Le théorème ne s''applique pas, mais cela ne contredit rien : c''est une **implication** (adjacentes → même limite), pas une équivalence.","tip_fr":"Le théorème donne une condition SUFFISANTE de convergence, pas nécessaire. Il y a d''autres façons d''avoir la même limite."}]}}]}]}'::jsonb WHERE code = 'seq_adjacent';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Limites de fonctions","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Limite en un point, à l''infini, formes indéterminées, factorisation, quantités conjuguées.","exercices":[{"number":1,"title_fr":"Calcul direct","points":4,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 1}(x^2 + 3x - 2)$.","points":1,"solution":{"steps":[{"text_fr":"Polynôme continu partout. Substitution directe : $1 + 3 - 2 = 2$."}],"final_answer_fr":"$\\lim = 2$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{x^2 - 4}{x - 2}$.","points":1,"solution":{"steps":[{"text_fr":"Substitution directe possible : $(0 - 4)/(0 - 2) = -4/-2 = 2$."}],"final_answer_fr":"$\\lim = 2$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 2} \\dfrac{x^2 - 4}{x - 2}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$ — factoriser : $x^2 - 4 = (x-2)(x+2)$. Donc $\\dfrac{x^2-4}{x-2} = x + 2$ pour $x \\ne 2$."},{"text_fr":"$\\lim_{x \\to 2}(x+2) = 4$."}],"final_answer_fr":"$\\lim = 4$"}}]},{"number":2,"title_fr":"Limites à l''infini","points":5,"preamble_fr":"Calculer ces limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{3x^2 - x}{x^2 + 5}$.","points":2,"solution":{"steps":[{"text_fr":"Quotient de polynômes de **même degré 2**. Rapport des coefficients dominants : $3/1 = 3$."}],"final_answer_fr":"$\\lim = 3$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{x + 1}{x^2}$.","points":1,"solution":{"steps":[{"text_fr":"Numérateur degré 1, dénominateur degré 2 — dénominateur l''emporte. Limite = 0."}],"final_answer_fr":"$\\lim = 0$"}},{"number":3,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{x^3 + 1}{x}$.","points":1,"solution":{"steps":[{"text_fr":"Numérateur degré 3, dénominateur degré 1 — numérateur l''emporte. $\\dfrac{x^3 + 1}{x} = x^2 + 1/x \\to +\\infty$."}],"final_answer_fr":"$\\lim = +\\infty$"}},{"number":4,"stem_fr":"$\\lim_{x \\to -\\infty}\\sqrt{x^2 + 1} + x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $+\\infty - \\infty$. Quantité conjuguée : multiplier par $(\\sqrt{x^2+1} - x)/(\\sqrt{x^2+1} - x)$."},{"text_fr":"On obtient $\\dfrac{1}{\\sqrt{x^2+1} - x}$. Pour $x \\to -\\infty$, $-x \\to +\\infty$, donc dénominateur $\\to +\\infty$, fraction $\\to 0$."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":3,"title_fr":"Limites latérales","points":5,"preamble_fr":"On considère $f(x) = \\dfrac{1}{x}$.","questions":[{"number":1,"stem_fr":"Calculer $\\lim_{x \\to 0^+} f$ et $\\lim_{x \\to 0^-} f$.","points":3,"solution":{"steps":[{"text_fr":"$x \\to 0^+$ : $x > 0$ très petit, donc $1/x \\to +\\infty$."},{"text_fr":"$x \\to 0^-$ : $x < 0$ très petit, donc $1/x \\to -\\infty$."},{"text_fr":"Limites latérales différentes → **pas de limite en 0**. La courbe a une asymptote verticale en $x = 0$."}],"final_answer_fr":"$\\lim_{0^+} = +\\infty$, $\\lim_{0^-} = -\\infty$"}},{"number":2,"stem_fr":"Calculer $\\lim_{x \\to \\pm\\infty} f(x)$.","points":2,"solution":{"steps":[{"text_fr":"À $\\pm\\infty$ : $1/x \\to 0$. La courbe a une asymptote horizontale $y = 0$."},{"text_fr":"**Résumé** : la courbe de $1/x$ a deux branches (hyperbole), avec asymptotes $y = 0$ et $x = 0$."}],"final_answer_fr":"$\\lim = 0$ aux deux bornes"}}]},{"number":4,"title_fr":"Asymptote oblique","points":6,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 + 1}{x - 1}$ définie sur $\\mathbb{R} \\setminus \\{1\\}$.","questions":[{"number":1,"stem_fr":"Effectuer la division euclidienne et écrire $f(x) = ax + b + \\dfrac{c}{x - 1}$.","points":3,"solution":{"steps":[{"text_fr":"Division : $x^2 + 1 = (x - 1) \\cdot x + (x + 1) = (x - 1)(x + 1) + 2$."},{"text_fr":"Donc $f(x) = x + 1 + \\dfrac{2}{x - 1}$."}],"final_answer_fr":"$f(x) = x + 1 + \\dfrac{2}{x-1}$"}},{"number":2,"stem_fr":"En déduire l''asymptote oblique de la courbe en $\\pm\\infty$.","points":3,"solution":{"steps":[{"text_fr":"Quand $x \\to \\pm\\infty$ : $\\dfrac{2}{x-1} \\to 0$, donc $f(x) - (x + 1) \\to 0$."},{"text_fr":"La courbe $y = f(x)$ admet la droite $y = x + 1$ pour **asymptote oblique** en $\\pm\\infty$.","tip_fr":"Asymptote oblique : on prend la partie polynômiale après division euclidienne. Le reste tend vers 0."}],"final_answer_fr":"$y = x + 1$ asymptote oblique"}}]}]}'::jsonb WHERE code = 'limit_def';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Calcul de limites avancé","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Techniques avancées : factorisation, conjugué, taux d''accroissement, croissances comparées $\\ln/\\exp/x^n$.","exercices":[{"number":1,"title_fr":"Formes 0/0 par factorisation","points":5,"preamble_fr":"Calculer les limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x - 3}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$. Factoriser : $x^2 - 9 = (x-3)(x+3)$."},{"text_fr":"$\\dfrac{(x-3)(x+3)}{x-3} = x + 3 \\to 6$ quand $x \\to 3$."}],"final_answer_fr":"$\\lim = 6$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 1} \\dfrac{x^3 - 1}{x^2 - 1}$.","points":3,"solution":{"steps":[{"text_fr":"Forme $0/0$. Numérateur : $x^3 - 1 = (x-1)(x^2 + x + 1)$. Dénominateur : $x^2 - 1 = (x-1)(x+1)$."},{"text_fr":"Fraction : $\\dfrac{(x-1)(x^2+x+1)}{(x-1)(x+1)} = \\dfrac{x^2+x+1}{x+1}$ (pour $x \\ne 1$)."},{"text_fr":"Limite en 1 : $\\dfrac{3}{2} = 1{,}5$."}],"final_answer_fr":"$\\lim = 3/2$"}}]},{"number":2,"title_fr":"Quantité conjuguée","points":5,"preamble_fr":"Calculer.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\sqrt{1 + x} - 1}{x}$.","points":3,"solution":{"steps":[{"text_fr":"Forme $0/0$. Multiplier haut et bas par la quantité conjuguée $\\sqrt{1+x} + 1$."},{"text_fr":"$\\dfrac{(\\sqrt{1+x} - 1)(\\sqrt{1+x} + 1)}{x(\\sqrt{1+x} + 1)} = \\dfrac{(1+x) - 1}{x(\\sqrt{1+x} + 1)} = \\dfrac{x}{x(\\sqrt{1+x} + 1)} = \\dfrac{1}{\\sqrt{1+x} + 1}$."},{"text_fr":"Limite en 0 : $\\dfrac{1}{1 + 1} = 1/2$.","tip_fr":"La quantité conjuguée $a - b$ multipliée par $a + b$ donne $a^2 - b^2$ — fait disparaître les racines carrées."}],"final_answer_fr":"$\\lim = 1/2$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty}\\sqrt{x^2 + x} - x$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. Conjuguée : multiplier par $(\\sqrt{x^2+x} + x)/(\\sqrt{x^2+x} + x)$."},{"text_fr":"Numérateur : $x^2 + x - x^2 = x$. Dénominateur : $\\sqrt{x^2+x} + x \\sim 2x$ à l''infini."},{"text_fr":"Donc fraction $\\sim x/(2x) = 1/2$. Limite = $1/2$."}],"final_answer_fr":"$\\lim = 1/2$"}}]},{"number":3,"title_fr":"Taux d''accroissement","points":5,"preamble_fr":"Reconnaître un taux d''accroissement pour calculer.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\sin x}{x}$.","points":2,"solution":{"steps":[{"text_fr":"C''est $\\dfrac{\\sin x - \\sin 0}{x - 0}$ = taux d''accroissement de $\\sin$ entre 0 et $x$. Limite = $\\sin''(0) = \\cos 0 = 1$."},{"text_fr":"**Limite usuelle** : $\\lim_{x \\to 0} \\dfrac{\\sin x}{x} = 1$. À mémoriser absolument."}],"final_answer_fr":"$\\lim = 1$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{e^x - 1}{x}$.","points":2,"solution":{"steps":[{"text_fr":"Taux d''accroissement de $\\exp$ en 0 : limite = $\\exp''(0) = e^0 = 1$.","tip_fr":"Limites usuelles : $\\lim_{0} \\dfrac{\\sin x}{x} = 1$, $\\lim_{0} \\dfrac{e^x - 1}{x} = 1$, $\\lim_{0} \\dfrac{\\ln(1+x)}{x} = 1$."}],"final_answer_fr":"$\\lim = 1$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\ln(1 + x)}{x}$.","points":1,"solution":{"steps":[{"text_fr":"Taux d''accroissement de $\\ln$ en 1 (avec changement de variable) : $\\ln(1+x) = \\ln(1+x) - \\ln(1)$, dérivée en 1 = $1/1 = 1$."}],"final_answer_fr":"$\\lim = 1$"}}]},{"number":4,"title_fr":"Croissances comparées","points":5,"preamble_fr":"Calculer les limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{\\ln x}{x}$ et $\\dfrac{\\ln x}{x^2}$.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : à l''infini, toute puissance positive de $x$ l''emporte sur $\\ln x$. $\\lim \\dfrac{\\ln x}{x^\\alpha} = 0$ pour tout $\\alpha > 0$."},{"text_fr":"Les deux limites valent **0**."}],"final_answer_fr":"$\\lim = 0$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{e^x}{x^{10}}$.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : à l''infini, l''exponentielle l''emporte sur toute puissance. $\\lim \\dfrac{e^x}{x^n} = +\\infty$ pour tout $n$."},{"text_fr":"Donc $\\lim = +\\infty$. Hiérarchie : $\\exp \\gg x^n \\gg \\ln$ à l''infini.","tip_fr":"Cette hiérarchie est universelle — elle décide qui ''gagne'' dans les formes indéterminées $\\infty/\\infty$ ou $\\infty \\cdot 0$."}],"final_answer_fr":"$\\lim = +\\infty$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0^+} x \\ln x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $0 \\cdot (-\\infty)$. Changement de variable $u = 1/x$ : $x \\ln x = (1/u) \\ln(1/u) = -\\ln(u)/u \\to 0$ quand $u \\to +\\infty$."},{"text_fr":"Donc $\\lim_{0^+} x \\ln x = 0$. Limite usuelle."}],"final_answer_fr":"$\\lim = 0$"}}]}]}'::jsonb WHERE code = 'limit_calc';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Continuité","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Définition de la continuité, prolongement par continuité, fonctions usuelles, opérations.","exercices":[{"number":1,"title_fr":"Définition et exemples","points":4,"preamble_fr":"On rappelle : $f$ est continue en $a$ ssi $\\lim_{x \\to a} f(x) = f(a)$.","questions":[{"number":1,"stem_fr":"Étudier la continuité de $f(x) = \\begin{cases} x + 1 & \\text{si } x \\le 2 \\\\ x^2 - 1 & \\text{si } x > 2 \\end{cases}$ en $x = 2$.","points":3,"solution":{"steps":[{"text_fr":"Valeur en 2 : $f(2) = 2 + 1 = 3$ (cas $x \\le 2$)."},{"text_fr":"**Limite à gauche** : $\\lim_{x \\to 2^-} f(x) = \\lim x + 1 = 3$ ✓."},{"text_fr":"**Limite à droite** : $\\lim_{x \\to 2^+} f(x) = \\lim x^2 - 1 = 4 - 1 = 3$ ✓."},{"text_fr":"Les deux limites latérales valent $f(2) = 3$ → $f$ est **continue en 2**. La fonction se ''recolle'' parfaitement à $x = 2$.","tip_fr":"Pour une fonction définie par morceaux, vérifier la continuité aux ''points de raccord'' = points où la définition change."}],"final_answer_fr":"Continue en 2"}},{"number":2,"stem_fr":"Que dire si la définition était $x^2 + 1$ pour $x > 2$ ?","points":1,"solution":{"steps":[{"text_fr":"Limite à droite : $\\lim x^2 + 1 = 5 \\ne f(2) = 3$. **Discontinuité** en 2 — saut de 2."}],"final_answer_fr":"Discontinue (saut)"}}]},{"number":2,"title_fr":"Prolongement par continuité","points":5,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 - 1}{x - 1}$ définie sur $\\mathbb{R} \\setminus \\{1\\}$.","questions":[{"number":1,"stem_fr":"Montrer qu''on peut prolonger $f$ par continuité en $x = 1$.","points":3,"solution":{"steps":[{"text_fr":"$f$ n''est pas définie en 1 (dénominateur s''annule). Étudions la limite : $\\dfrac{x^2 - 1}{x - 1} = \\dfrac{(x-1)(x+1)}{x-1} = x + 1$ pour $x \\ne 1$."},{"text_fr":"Donc $\\lim_{x \\to 1} f(x) = 2$ existe et est finie."},{"text_fr":"**Prolongement par continuité** : définir $\\tilde f(1) = 2$ rend $\\tilde f$ continue en 1. La fonction prolongée est simplement $x + 1$ partout.","tip_fr":"Quand une fonction a une discontinuité ''apparente'' (forme $0/0$), on peut souvent la prolonger par continuité."}],"final_answer_fr":"$\\tilde f(1) = 2$, continue partout"}},{"number":2,"stem_fr":"Peut-on prolonger $g(x) = 1/x$ par continuité en $x = 0$ ?","points":2,"solution":{"steps":[{"text_fr":"Limites latérales : $\\lim_{0^+} 1/x = +\\infty$ et $\\lim_{0^-} 1/x = -\\infty$."},{"text_fr":"Pas de limite finie en 0 → **impossible** de prolonger par continuité. La discontinuité de $1/x$ en 0 est essentielle (asymptote verticale)."}],"final_answer_fr":"Non (pas de limite finie en 0)"}}]},{"number":3,"title_fr":"Continuité des fonctions usuelles","points":5,"preamble_fr":"Étudier la continuité des fonctions suivantes sur leur ensemble de définition.","questions":[{"number":1,"stem_fr":"$f(x) = \\sqrt{x}$.","points":1,"solution":{"steps":[{"text_fr":"Définie sur $[0, +\\infty[$. Continue sur cet intervalle (fonction usuelle)."}]}},{"number":2,"stem_fr":"$g(x) = \\ln x$.","points":1,"solution":{"steps":[{"text_fr":"Définie sur $]0, +\\infty[$. Continue sur cet intervalle."}]}},{"number":3,"stem_fr":"$h(x) = \\dfrac{1}{x^2 + 1}$.","points":1,"solution":{"steps":[{"text_fr":"$x^2 + 1 > 0$ pour tout $x$, donc $h$ est définie sur $\\mathbb{R}$. Continue partout (quotient de fonctions continues sans annulation du dénominateur)."}]}},{"number":4,"stem_fr":"$k(x) = \\dfrac{\\sin x}{x}$ avec $k(0) = 1$.","points":2,"solution":{"steps":[{"text_fr":"Sur $\\mathbb{R}^*$, continue (quotient de continues). En 0 : $\\lim_{x \\to 0} \\sin x/x = 1 = k(0)$ ✓."},{"text_fr":"**Continue sur $\\mathbb{R}$**. Cette fonction est célèbre — c''est la fonction ''sinc'' utilisée en traitement du signal."}]}}]},{"number":4,"title_fr":"Opérations sur les fonctions continues","points":6,"preamble_fr":"On rappelle : somme/produit/quotient/composée de fonctions continues est continue (avec conditions classiques).","questions":[{"number":1,"stem_fr":"Justifier la continuité de $f(x) = \\sqrt{x^2 + 1}$.","points":2,"solution":{"steps":[{"text_fr":"$x \\mapsto x^2 + 1$ est polynômiale, continue sur $\\mathbb{R}$."},{"text_fr":"$x^2 + 1 \\ge 1 > 0$, donc $\\sqrt{x^2 + 1}$ est bien définie. $\\sqrt{\\cdot}$ est continue sur $[0, +\\infty[$."},{"text_fr":"Composée de continues sur leur image → **$f$ continue sur $\\mathbb{R}$**."}]}},{"number":2,"stem_fr":"Continuité de $g(x) = \\dfrac{x + 1}{x^2 - 4}$. Préciser le domaine.","points":2,"solution":{"steps":[{"text_fr":"Dénominateur $x^2 - 4 = (x-2)(x+2) = 0 \\iff x = \\pm 2$. Donc domaine = $\\mathbb{R} \\setminus \\{-2, 2\\}$."},{"text_fr":"Quotient de polynômes (continus) avec dénominateur non nul → $g$ est **continue sur $\\mathbb{R} \\setminus \\{-2, 2\\}$**."}],"final_answer_fr":"Continue sur $\\mathbb{R} \\setminus \\{-2, 2\\}$"}},{"number":3,"stem_fr":"Que dire de la continuité de $h(x) = e^{1/x}$ sur $\\mathbb{R}^*$ ?","points":2,"solution":{"steps":[{"text_fr":"$x \\mapsto 1/x$ continue sur $\\mathbb{R}^*$. $\\exp$ continue partout. Composée → $h$ continue sur $\\mathbb{R}^*$."},{"text_fr":"En 0 : pas de limite finie ($\\lim_{0^+} e^{1/x} = +\\infty$, $\\lim_{0^-} e^{1/x} = 0$). Pas prolongeable."}]}}]}]}'::jsonb WHERE code = 'continuity';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Théorème des valeurs intermédiaires","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"TVI : $f$ continue sur $[a, b]$ et $k$ entre $f(a)$ et $f(b)$ → $\\exists c \\in [a, b] : f(c) = k$. Corollaire : $f(a) f(b) < 0$ → $f$ s''annule au moins une fois.","exercices":[{"number":1,"title_fr":"Application directe","points":5,"preamble_fr":"Montrer que les équations suivantes admettent au moins une solution dans l''intervalle indiqué.","questions":[{"number":1,"stem_fr":"$x^3 + x - 1 = 0$ sur $[0, 1]$.","points":3,"solution":{"steps":[{"text_fr":"Soit $p(x) = x^3 + x - 1$. $p$ est polynômiale donc **continue sur $\\mathbb{R}$**, en particulier sur $[0, 1]$."},{"text_fr":"Calcul : $p(0) = -1 < 0$, $p(1) = 1 + 1 - 1 = 1 > 0$."},{"text_fr":"0 est compris entre $p(0) = -1$ et $p(1) = 1$. Par le **TVI**, $\\exists c \\in [0, 1] : p(c) = 0$."},{"text_fr":"**Unicité** : $p''(x) = 3x^2 + 1 > 0$ partout → $p$ strictement croissante → unicité de la solution. $c \\approx 0{,}682$.","tip_fr":"Pour montrer l''**unicité**, prouver la monotonie de $f$ via l''étude du signe de $f''$."}],"final_answer_fr":"$\\exists ! c \\in ]0, 1[$ avec $p(c) = 0$"}},{"number":2,"stem_fr":"$\\cos x = x$ sur $[0, \\pi/2]$.","points":2,"solution":{"steps":[{"text_fr":"Poser $g(x) = \\cos x - x$. Continue sur $\\mathbb{R}$ (différence de continues)."},{"text_fr":"$g(0) = 1 > 0$, $g(\\pi/2) = 0 - \\pi/2 \\approx -1{,}57 < 0$. Changement de signe → par TVI, $\\exists c : g(c) = 0 \\iff \\cos c = c$. Numériquement $c \\approx 0{,}739$."}],"final_answer_fr":"$\\exists c \\in ]0, \\pi/2[$ : $\\cos c = c$"}}]},{"number":2,"title_fr":"Méthode de dichotomie","points":5,"preamble_fr":"On veut approximer la solution $\\alpha$ de $f(x) = x^2 - 2 = 0$ sur $[1, 2]$.","questions":[{"number":1,"stem_fr":"Justifier qu''une solution existe dans $[1, 2]$.","points":1,"solution":{"steps":[{"text_fr":"$f$ continue, $f(1) = -1 < 0$, $f(2) = 2 > 0$. Par TVI, solution dans $]1, 2[$."},{"text_fr":"Bien sûr la solution est $\\sqrt 2 \\approx 1{,}414$."}]}},{"number":2,"stem_fr":"Appliquer 3 étapes de dichotomie pour encadrer $\\alpha$.","points":4,"solution":{"steps":[{"text_fr":"**Itération 1** : milieu $m_1 = 1{,}5$. $f(1{,}5) = 0{,}25 > 0$. Donc la solution est dans $]1, 1{,}5[$."},{"text_fr":"**Itération 2** : $m_2 = 1{,}25$. $f(1{,}25) = -0{,}4375 < 0$. Donc dans $]1{,}25, 1{,}5[$."},{"text_fr":"**Itération 3** : $m_3 = 1{,}375$. $f(1{,}375) = -0{,}109 < 0$. Donc dans $]1{,}375, 1{,}5[$."},{"text_fr":"Encadrement après 3 étapes : $1{,}375 < \\sqrt 2 < 1{,}5$. Précision : 0,125.","tip_fr":"Dichotomie : à chaque étape, on divise l''intervalle par 2. Convergence linéaire — précision multipliée par 2 à chaque étape."}],"final_answer_fr":"$\\alpha \\in [1{,}375, 1{,}5]$ après 3 étapes"}}]},{"number":3,"title_fr":"TVI pour équations transcendantes","points":5,"preamble_fr":"Soit $f(x) = e^x + x - 5$.","questions":[{"number":1,"stem_fr":"Montrer que l''équation $f(x) = 0$ admet une **unique** solution dans $\\mathbb{R}$.","points":4,"solution":{"steps":[{"text_fr":"**Existence** : $f$ est continue (somme de continues). $f(0) = 1 + 0 - 5 = -4 < 0$, $f(2) = e^2 + 2 - 5 \\approx 4{,}39 > 0$. TVI → solution dans $]0, 2[$."},{"text_fr":"**Unicité** : $f''(x) = e^x + 1 > 0$ partout (somme de positifs). $f$ strictement croissante → solution unique."},{"text_fr":"**Domaine** : $\\lim_{-\\infty} f = -\\infty + (-\\infty) - 5 = -\\infty$. $\\lim_{+\\infty} f = +\\infty$. Donc $f$ atteint toutes les valeurs réelles, et l''unique solution est dans $\\mathbb{R}$.","tip_fr":"Combiner : (1) TVI pour l''existence, (2) monotonie stricte pour l''unicité, (3) extension du domaine via les limites aux bornes."}],"final_answer_fr":"$\\exists ! \\alpha \\approx 1{,}306$"}},{"number":2,"stem_fr":"Donner un encadrement de la solution à $10^{-1}$ près.","points":1,"solution":{"steps":[{"text_fr":"Test $f(1{,}3) = e^{1{,}3} + 1{,}3 - 5 \\approx 3{,}669 + 1{,}3 - 5 = -0{,}031 < 0$. $f(1{,}4) \\approx 4{,}055 + 1{,}4 - 5 = 0{,}455 > 0$."},{"text_fr":"Donc $\\alpha \\in ]1{,}3,\\, 1{,}4[$."}],"final_answer_fr":"$\\alpha \\in ]1{,}3, 1{,}4[$"}}]},{"number":4,"title_fr":"Limitations du TVI","points":5,"preamble_fr":"Le TVI donne l''existence, pas la valeur. Discuter ses limites.","questions":[{"number":1,"stem_fr":"Pourquoi la condition ''continue sur $[a, b]$'' est-elle essentielle ? Donner un contre-exemple.","points":3,"solution":{"steps":[{"text_fr":"Contre-exemple : $f(x) = 1/x$ sur $[-1, 1] \\setminus \\{0\\}$. $f(-1) = -1$, $f(1) = 1$, 0 est entre les deux."},{"text_fr":"Pourtant, $f$ ne s''annule **jamais** sur ce domaine — la discontinuité en 0 fait que la courbe ''saute'' $-\\infty \\to +\\infty$ sans passer par 0."},{"text_fr":"Conclusion : sans continuité, le TVI ne s''applique pas. La continuité est essentielle."}]}},{"number":2,"stem_fr":"Le TVI donne-t-il l''unicité ?","points":2,"solution":{"steps":[{"text_fr":"**Non** — il donne juste l''existence d''au moins un $c$. Si $f$ n''est pas monotone, il peut y avoir plusieurs solutions."},{"text_fr":"Exemple : $f(x) = x^2 - 1$ sur $[-2, 2]$. $f(-2) = 3 > 0$, $f(2) = 3 > 0$ — le TVI ne s''applique pas pour conclure à l''existence d''une racine ici (0 n''est pas entre 3 et 3). Mais en fait il y en a deux : $x = \\pm 1$. Le TVI ne les voit pas car les bornes sont du même signe."},{"text_fr":"Sur $[-2, 0]$ : $f(-2) = 3$, $f(0) = -1$ → TVI donne une racine dans $[-2, 0]$ (à savoir -1). Mais le TVI seul ne détecte pas l''autre racine.","tip_fr":"Pour des fonctions non-monotones, découper l''intervalle en sous-intervalles monotones avant d''appliquer le TVI."}]}}]}]}'::jsonb WHERE code = 'tvi';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Dérivée — concept et calcul","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Définition par taux d''accroissement, interprétation géométrique (tangente), dérivées usuelles.","exercices":[{"number":1,"title_fr":"Définition","points":5,"preamble_fr":"Soit $f(x) = x^2 - 3x$.","questions":[{"number":1,"stem_fr":"Calculer le taux d''accroissement $\\tau_h$ entre 2 et $2 + h$.","points":2,"solution":{"steps":[{"text_fr":"$f(2+h) = (2+h)^2 - 3(2+h) = 4 + 4h + h^2 - 6 - 3h = h^2 + h - 2$."},{"text_fr":"$f(2) = 4 - 6 = -2$."},{"text_fr":"$\\tau_h = \\dfrac{f(2+h) - f(2)}{h} = \\dfrac{h^2 + h - 2 - (-2)}{h} = \\dfrac{h^2 + h}{h} = h + 1$."}],"final_answer_fr":"$\\tau_h = h + 1$"}},{"number":2,"stem_fr":"En déduire $f''(2)$.","points":2,"solution":{"steps":[{"text_fr":"$f''(2) = \\lim_{h \\to 0} \\tau_h = \\lim (h + 1) = 1$."},{"text_fr":"Vérification : $f''(x) = 2x - 3$, $f''(2) = 4 - 3 = 1$ ✓."}],"final_answer_fr":"$f''(2) = 1$"}},{"number":3,"stem_fr":"Donner l''équation de la tangente en $x = 2$.","points":1,"solution":{"steps":[{"text_fr":"**Équation** : $y = f(2) + f''(2)(x - 2) = -2 + 1 \\cdot (x - 2) = x - 4$."}],"final_answer_fr":"$y = x - 4$"}}]},{"number":2,"title_fr":"Dérivées usuelles","points":5,"preamble_fr":"Calculer les dérivées.","questions":[{"number":1,"stem_fr":"$f(x) = x^5$, $g(x) = 1/x$, $h(x) = \\sqrt{x}$.","points":3,"solution":{"steps":[{"text_fr":"$f''(x) = 5 x^4$ (règle des puissances)."},{"text_fr":"$g(x) = x^{-1} \\Rightarrow g''(x) = -x^{-2} = -1/x^2$."},{"text_fr":"$h(x) = x^{1/2} \\Rightarrow h''(x) = (1/2) x^{-1/2} = 1/(2\\sqrt{x})$."}]}},{"number":2,"stem_fr":"$\\sin x, \\cos x, e^x, \\ln x$.","points":2,"solution":{"steps":[{"text_fr":"$(\\sin x)'' = \\cos x$, $(\\cos x)'' = -\\sin x$."},{"text_fr":"$(e^x)'' = e^x$ (sa propre dérivée), $(\\ln x)'' = 1/x$.","tip_fr":"Mémoriser ces 4 dérivées usuelles : indispensable. Avec les règles d''opérations, on peut tout dériver."}]}}]},{"number":3,"title_fr":"Sens de variation","points":5,"preamble_fr":"Soit $f(x) = x^3 - 3x + 2$.","questions":[{"number":1,"stem_fr":"Calculer $f''(x)$ et étudier son signe.","points":3,"solution":{"steps":[{"text_fr":"$f''(x) = 3 x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)$."},{"text_fr":"Racines : $x = -1$ et $x = 1$. Coefficient dominant positif → $f''$ positive en dehors des racines."},{"text_fr":"Signes : sur $]-\\infty, -1[$ : $f'' > 0$. Sur $]-1, 1[$ : $f'' < 0$. Sur $]1, +\\infty[$ : $f'' > 0$."}]}},{"number":2,"stem_fr":"Donner le tableau de variations et les extrema.","points":2,"solution":{"steps":[{"text_fr":"$f$ croissante sur $]-\\infty, -1[$, décroissante sur $]-1, 1[$, croissante sur $]1, +\\infty[$."},{"text_fr":"**Maximum local** en $x = -1$ : $f(-1) = -1 + 3 + 2 = 4$. **Minimum local** en $x = 1$ : $f(1) = 1 - 3 + 2 = 0$."}],"final_answer_fr":"Max local en $-1$ ($=4$), min local en $1$ ($=0$)"}}]},{"number":4,"title_fr":"Tangente — problème géométrique","points":5,"preamble_fr":"Soit la parabole $\\mathcal{P}$ d''équation $y = x^2$.","questions":[{"number":1,"stem_fr":"Trouver les points de $\\mathcal{P}$ où la tangente a pour pente 4.","points":3,"solution":{"steps":[{"text_fr":"Pente en un point $(a, a^2)$ : $f''(a) = 2a$."},{"text_fr":"$2a = 4 \\iff a = 2$. Point : $(2, 4)$."},{"text_fr":"Tangente : $y = 4 + 4(x - 2) = 4x - 4$."}],"final_answer_fr":"Point $(2, 4)$, tangente $y = 4x - 4$"}},{"number":2,"stem_fr":"Existe-t-il un point de $\\mathcal{P}$ où la tangente est parallèle à la droite $y = -3x$ ?","points":2,"solution":{"steps":[{"text_fr":"Pente -3 → $2a = -3 \\iff a = -3/2$. Point : $(-3/2, 9/4)$."},{"text_fr":"**Oui**, ce point existe. La tangente y a pour équation $y = 9/4 - 3(x + 3/2) = -3x - 9/4$, parallèle à $y = -3x$ ✓."}],"final_answer_fr":"Point $(-3/2, 9/4)$"}}]}]}'::jsonb WHERE code = 'deriv_basic';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Règles de dérivation","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Linéarité, produit $(uv)'' = u''v + uv''$, quotient $(u/v)'' = (u''v - uv'')/v^2$, composition $(f \\circ g)'' = (f'' \\circ g) \\cdot g''$.","exercices":[{"number":1,"title_fr":"Linéarité et puissances","points":4,"preamble_fr":"Dériver.","questions":[{"number":1,"stem_fr":"$f(x) = 3x^4 - 2x^3 + 5x - 7$.","points":2,"solution":{"steps":[{"text_fr":"Linéarité : dériver terme à terme. $f''(x) = 12 x^3 - 6 x^2 + 5$."}],"final_answer_fr":"$f''(x) = 12x^3 - 6x^2 + 5$"}},{"number":2,"stem_fr":"$g(x) = \\dfrac{2}{x^3} + 4\\sqrt{x}$.","points":2,"solution":{"steps":[{"text_fr":"$g(x) = 2 x^{-3} + 4 x^{1/2}$."},{"text_fr":"$g''(x) = -6 x^{-4} + 2 x^{-1/2} = -6/x^4 + 2/\\sqrt x$."}],"final_answer_fr":"$g''(x) = -6/x^4 + 2/\\sqrt{x}$"}}]},{"number":2,"title_fr":"Produit","points":5,"preamble_fr":"Utiliser la règle du produit.","questions":[{"number":1,"stem_fr":"$f(x) = x \\sin x$.","points":2,"solution":{"steps":[{"text_fr":"Règle : $(uv)'' = u''v + uv''$. $u = x, u'' = 1$ ; $v = \\sin x, v'' = \\cos x$."},{"text_fr":"$f''(x) = 1 \\cdot \\sin x + x \\cdot \\cos x = \\sin x + x \\cos x$."}],"final_answer_fr":"$f''(x) = \\sin x + x \\cos x$"}},{"number":2,"stem_fr":"$g(x) = (x^2 + 1)(x^3 - 2)$.","points":2,"solution":{"steps":[{"text_fr":"$g''(x) = 2x(x^3 - 2) + (x^2 + 1) \\cdot 3 x^2 = 2x^4 - 4x + 3x^4 + 3x^2 = 5x^4 + 3x^2 - 4x$."},{"text_fr":"Vérification (développer puis dériver) : $g(x) = x^5 + x^3 - 2x^2 - 2$, $g''(x) = 5x^4 + 3x^2 - 4x$ ✓."}],"final_answer_fr":"$g''(x) = 5x^4 + 3x^2 - 4x$"}},{"number":3,"stem_fr":"$h(x) = x^2 e^x$.","points":1,"solution":{"steps":[{"text_fr":"$h''(x) = 2x \\cdot e^x + x^2 \\cdot e^x = (2x + x^2) e^x = x(x + 2) e^x$."}],"final_answer_fr":"$h''(x) = x(x+2) e^x$"}}]},{"number":3,"title_fr":"Quotient","points":5,"preamble_fr":"Utiliser la règle du quotient.","questions":[{"number":1,"stem_fr":"$f(x) = \\dfrac{x}{x^2 + 1}$.","points":3,"solution":{"steps":[{"text_fr":"Règle : $(u/v)'' = (u''v - uv'')/v^2$. $u = x, u'' = 1$ ; $v = x^2 + 1, v'' = 2x$."},{"text_fr":"Numérateur : $1 \\cdot (x^2 + 1) - x \\cdot 2x = x^2 + 1 - 2x^2 = 1 - x^2$."},{"text_fr":"Dénominateur : $(x^2 + 1)^2$. Donc $f''(x) = \\dfrac{1 - x^2}{(x^2 + 1)^2}$."}],"final_answer_fr":"$f''(x) = \\dfrac{1 - x^2}{(x^2+1)^2}$"}},{"number":2,"stem_fr":"$g(x) = \\dfrac{1 + x}{1 - x}$ (pour $x \\ne 1$).","points":2,"solution":{"steps":[{"text_fr":"$u = 1 + x, u'' = 1$ ; $v = 1 - x, v'' = -1$."},{"text_fr":"$g''(x) = \\dfrac{1 \\cdot (1-x) - (1+x)(-1)}{(1-x)^2} = \\dfrac{1 - x + 1 + x}{(1-x)^2} = \\dfrac{2}{(1-x)^2}$."},{"text_fr":"Observation : $g''(x) > 0$ partout (sauf en 1 où non définie) → $g$ strictement croissante sur ses deux intervalles."}],"final_answer_fr":"$g''(x) = 2/(1-x)^2$"}}]},{"number":4,"title_fr":"Composition","points":6,"preamble_fr":"Utiliser la règle de la chaîne.","questions":[{"number":1,"stem_fr":"$f(x) = (3x + 1)^4$.","points":2,"solution":{"steps":[{"text_fr":"**Composition** $u^4$ avec $u(x) = 3x + 1$. Règle : $(u^n)'' = n u^{n-1} u''$."},{"text_fr":"$u'' = 3$, donc $f''(x) = 4 (3x + 1)^3 \\cdot 3 = 12(3x + 1)^3$.","mistake_fr":"Ne pas oublier le $\\times 3$ (dérivée de l''intérieur) — c''est l''erreur la plus fréquente."}],"final_answer_fr":"$f''(x) = 12(3x+1)^3$"}},{"number":2,"stem_fr":"$g(x) = \\sqrt{x^2 + 1}$.","points":2,"solution":{"steps":[{"text_fr":"Composition $\\sqrt{u}$ avec $u = x^2 + 1$. Règle : $(\\sqrt u)'' = u''/(2\\sqrt u)$."},{"text_fr":"$u'' = 2x$, donc $g''(x) = \\dfrac{2x}{2\\sqrt{x^2+1}} = \\dfrac{x}{\\sqrt{x^2+1}}$."}],"final_answer_fr":"$g''(x) = x/\\sqrt{x^2+1}$"}},{"number":3,"stem_fr":"$h(x) = e^{-x^2}$.","points":2,"solution":{"steps":[{"text_fr":"Composition $e^u$ avec $u = -x^2$. Règle : $(e^u)'' = u'' e^u$."},{"text_fr":"$u'' = -2x$, donc $h''(x) = -2x e^{-x^2}$."},{"text_fr":"**Fonction célèbre** : $e^{-x^2}$ est la cloche de Gauss (densité de probabilité normale, à un facteur près)."}],"final_answer_fr":"$h''(x) = -2x e^{-x^2}$"}}]}]}'::jsonb WHERE code = 'deriv_rules';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Applications de la dérivation","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Étude complète de fonction : domaine, variations, extrema, asymptotes, tracé. Problèmes d''optimisation.","exercices":[{"number":1,"title_fr":"Étude complète","points":6,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 - 1}{x}$ définie sur $\\mathbb{R}^*$.","questions":[{"number":1,"stem_fr":"Étude complète de $f$.","points":5,"subparts":[{"letter":"a","stem_fr":"Calculer $f''(x)$ et étudier son signe.","points":2,"solution":{"steps":[{"text_fr":"$f(x) = x - 1/x$. $f''(x) = 1 + 1/x^2 > 0$ partout. $f$ **strictement croissante** sur ses deux intervalles $]-\\infty, 0[$ et $]0, +\\infty[$."}],"final_answer_fr":"$f''(x) = 1 + 1/x^2 > 0$"}},{"letter":"b","stem_fr":"Calculer les limites aux bornes.","points":2,"solution":{"steps":[{"text_fr":"$\\lim_{x \\to +\\infty} f = +\\infty$ (dominé par $x$). $\\lim_{x \\to -\\infty} f = -\\infty$."},{"text_fr":"$\\lim_{x \\to 0^+} f = -\\infty$ (le terme $-1/x \\to -\\infty$). $\\lim_{x \\to 0^-} f = +\\infty$."}]}},{"letter":"c","stem_fr":"Étudier les asymptotes.","points":1,"solution":{"steps":[{"text_fr":"**Asymptote verticale** : $x = 0$ (les limites en $0^\\pm$ sont infinies)."},{"text_fr":"**Asymptote oblique** à l''infini : $f(x) = x - 1/x$. Le terme $-1/x \\to 0$, donc $f(x) - x \\to 0$. La droite $y = x$ est asymptote oblique."}],"final_answer_fr":"Asymptote verticale $x=0$, oblique $y=x$"}}]}]},{"number":2,"title_fr":"Optimisation — boîte sans couvercle","points":5,"preamble_fr":"On veut fabriquer une boîte rectangulaire sans couvercle à partir d''une feuille de carton carrée de côté 30 cm, en découpant un carré de côté $x$ à chaque coin et en pliant. Volume $V(x) = x (30 - 2x)^2$, avec $0 < x < 15$.","questions":[{"number":1,"stem_fr":"Calculer $V''(x)$ et trouver la valeur de $x$ qui maximise le volume.","points":4,"solution":{"steps":[{"text_fr":"Règle du produit : $V''(x) = 1 \\cdot (30 - 2x)^2 + x \\cdot 2(30 - 2x)(-2) = (30 - 2x)^2 - 4x(30 - 2x)$."},{"text_fr":"Factoriser : $V''(x) = (30 - 2x)[(30 - 2x) - 4x] = (30 - 2x)(30 - 6x) = 12 (15 - x)(5 - x)$."},{"text_fr":"Racines de $V''$ : $x = 5$ et $x = 15$. $x = 15$ exclu (bord du domaine). Étude du signe sur $]0, 15[$ : $V''(0) = 12 \\cdot 15 \\cdot 5 = 900 > 0$ ; $V''(10) = 12 \\cdot 5 \\cdot (-5) = -300 < 0$. Donc $V''$ change de signe en $x = 5$ : **maximum**."},{"text_fr":"Volume maximum : $V(5) = 5 \\cdot 20^2 = 5 \\cdot 400 = 2000\\,cm^3 = 2\\,L$.","tip_fr":"Problème classique d''optimisation en BTS. La ''recette'' : exprimer la grandeur à optimiser comme fonction d''une variable, calculer la dérivée, trouver les points critiques."}],"final_answer_fr":"$x = 5$ cm, $V_{\\max} = 2000$ cm³"}}]},{"number":3,"title_fr":"Inégalité par étude de fonction","points":5,"preamble_fr":"Démontrer que pour tout $x > 0$, $\\ln(1 + x) < x$.","questions":[{"number":1,"stem_fr":"Étudier la fonction $f(x) = x - \\ln(1 + x)$ sur $[0, +\\infty[$.","points":4,"solution":{"steps":[{"text_fr":"$f(0) = 0 - \\ln 1 = 0$."},{"text_fr":"$f''(x) = 1 - \\dfrac{1}{1 + x} = \\dfrac{x}{1 + x}$. Sur $[0, +\\infty[$ : $x \\ge 0$ et $1 + x > 0$ → $f''(x) \\ge 0$."},{"text_fr":"$f'' > 0$ pour $x > 0$ → $f$ strictement croissante."},{"text_fr":"Conclusion : pour $x > 0$, $f(x) > f(0) = 0$, donc $x - \\ln(1+x) > 0 \\iff \\ln(1+x) < x$. ✓","tip_fr":"Pour démontrer $f(x) > g(x)$, étudier la fonction différence $h = f - g$ et montrer qu''elle est positive."}]}},{"number":2,"stem_fr":"En déduire l''inégalité $\\ln(2) < 1$ et donner un encadrement de $\\ln 2$.","points":1,"solution":{"steps":[{"text_fr":"Appliquer avec $x = 1$ : $\\ln(1 + 1) = \\ln 2 < 1$ ✓."},{"text_fr":"On peut aussi montrer $\\ln(1 + x) > x - x^2/2$ pour $x > 0$ (par étude similaire). Avec $x = 1$ : $\\ln 2 > 1/2$. Donc $1/2 < \\ln 2 < 1$. Valeur exacte : $\\ln 2 \\approx 0{,}693$."}],"final_answer_fr":"$1/2 < \\ln 2 < 1$"}}]},{"number":4,"title_fr":"Tangentes communes","points":4,"preamble_fr":"Soient $f(x) = x^2$ et $g(x) = -(x-2)^2 + 4$.","questions":[{"number":1,"stem_fr":"Trouver une tangente commune aux deux courbes.","points":4,"solution":{"steps":[{"text_fr":"Soit la tangente à $f$ en $(a, a^2)$ : pente $2a$, équation $y = 2a(x - a) + a^2 = 2ax - a^2$."},{"text_fr":"Soit la tangente à $g$ en $(b, -(b-2)^2 + 4)$ : pente $g''(b) = -2(b - 2)$, équation $y = -2(b-2)x + \\text{const}$."},{"text_fr":"Pour qu''elles coïncident : pentes égales $2a = -2(b-2) \\Rightarrow a = 2 - b$. Et ordonnées à l''origine égales : $-a^2 = -2(b-2) \\cdot 0 + g(b) - g''(b) \\cdot b$... calcul plus simple : la tangente à g au point b a pour équation $y = -2(b-2)x + (b^2 - 4)$ (en développant)."},{"text_fr":"Égalité : $2a = -2(b-2)$ et $-a^2 = b^2 - 4$. Substituer $a = 2 - b$ : $-(2-b)^2 = b^2 - 4 \\Rightarrow -(4 - 4b + b^2) = b^2 - 4 \\Rightarrow -4 + 4b - b^2 = b^2 - 4 \\Rightarrow 4b = 2 b^2 \\Rightarrow b = 0$ ou $b = 2$."},{"text_fr":"Pour $b = 2$ : $a = 0$, tangente $y = 0$ (axe Ox). Vérification : $f(0) = 0$, tangente horizontale ; et tangente à g au sommet $(2, 4)$ n''est pas l''axe Ox... mais à $(2, 0)$ - non, $g(2) = 4$. La tangente commune est à $y = 0$ entre $f(0) = 0$ et $g(0) = 0$... ah, $g(0) = -(0-2)^2 + 4 = -4 + 4 = 0$ ✓."}],"final_answer_fr":"Tangente commune : $y = 0$ entre $(0,0)$ pour les deux"}}]}]}'::jsonb WHERE code = 'deriv_apps';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Primitives","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Définition ($F'' = f$), calcul, unicité à une constante près, primitives usuelles.","exercices":[{"number":1,"title_fr":"Primitives usuelles","points":5,"preamble_fr":"Donner une primitive sur l''intervalle indiqué.","questions":[{"number":1,"stem_fr":"$f(x) = x^3 - 4x + 2$ sur $\\mathbb{R}$.","points":2,"solution":{"steps":[{"text_fr":"Linéarité de l''intégration. Pour $x^n$ ($n \\ne -1$) : primitive = $x^{n+1}/(n+1)$."},{"text_fr":"$F(x) = x^4/4 - 2x^2 + 2x + C$. Vérification : $F''(x) = x^3 - 4x + 2$ ✓."}],"final_answer_fr":"$F(x) = x^4/4 - 2x^2 + 2x + C$"}},{"number":2,"stem_fr":"$g(x) = 1/x^2$ sur $]0, +\\infty[$.","points":1,"solution":{"steps":[{"text_fr":"$g(x) = x^{-2}$, primitive $x^{-1}/(-1) = -1/x + C$. Vérification : $(-1/x)'' = 1/x^2$ ✓."}],"final_answer_fr":"$G(x) = -1/x + C$"}},{"number":3,"stem_fr":"$h(x) = \\sin(2x)$ sur $\\mathbb{R}$.","points":1,"solution":{"steps":[{"text_fr":"Composition : essayer $H(x) = -\\cos(2x)/2$. Vérification : $H''(x) = -(-\\sin 2x) \\cdot 2 / 2 = \\sin 2x$ ✓.","tip_fr":"Pour $\\sin(ax)$, primitive $-\\cos(ax)/a$. Pour $\\cos(ax)$, primitive $\\sin(ax)/a$. Le facteur $1/a$ compense la dérivation de l''argument."}],"final_answer_fr":"$H(x) = -\\cos(2x)/2 + C$"}},{"number":4,"stem_fr":"$k(x) = e^{3x + 1}$ sur $\\mathbb{R}$.","points":1,"solution":{"steps":[{"text_fr":"Primitive $K(x) = e^{3x+1}/3 + C$. Vérification : $K''(x) = 3 e^{3x+1}/3 = e^{3x+1}$ ✓."}],"final_answer_fr":"$K(x) = e^{3x+1}/3 + C$"}}]},{"number":2,"title_fr":"Primitive vérifiant une condition","points":5,"preamble_fr":"Soit $f(x) = 3 x^2 - 6x + 5$.","questions":[{"number":1,"stem_fr":"Trouver la primitive $F$ telle que $F(1) = 0$.","points":3,"solution":{"steps":[{"text_fr":"Forme générale : $F(x) = x^3 - 3 x^2 + 5x + C$."},{"text_fr":"Condition : $F(1) = 1 - 3 + 5 + C = 3 + C = 0 \\Rightarrow C = -3$."},{"text_fr":"Primitive : $F(x) = x^3 - 3 x^2 + 5x - 3$.","tip_fr":"Toute primitive a une **constante d''intégration** libre — fixée par une condition supplémentaire."}],"final_answer_fr":"$F(x) = x^3 - 3x^2 + 5x - 3$"}},{"number":2,"stem_fr":"Vérifier le résultat.","points":2,"solution":{"steps":[{"text_fr":"$F''(x) = 3x^2 - 6x + 5 = f(x)$ ✓."},{"text_fr":"$F(1) = 1 - 3 + 5 - 3 = 0$ ✓."}]}}]},{"number":3,"title_fr":"Reconnaître une dérivée","points":5,"preamble_fr":"Calculer les primitives suivantes en reconnaissant la forme $u''/u$ ou $u'' u^n$.","questions":[{"number":1,"stem_fr":"$\\int \\dfrac{2x}{x^2 + 1}\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"On reconnaît la forme $u''/u$ avec $u(x) = x^2 + 1$. La primitive est $\\ln|u| + C = \\ln(x^2 + 1) + C$ (valeur absolue inutile car $x^2 + 1 > 0$)."},{"text_fr":"Vérification : $(\\ln(x^2+1))'' = (2x)/(x^2+1)$ ✓."}],"final_answer_fr":"$\\ln(x^2 + 1) + C$"}},{"number":2,"stem_fr":"$\\int (2x + 1)^5\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Forme $u'' u^n$ ? On a $u = 2x + 1$, $u'' = 2$. Mais le facteur 2 manque. Réécrire : $(2x+1)^5 = (1/2) \\cdot 2 \\cdot (2x+1)^5$."},{"text_fr":"Primitive : $(1/2) \\cdot (2x+1)^6/6 = (2x+1)^6/12 + C$."},{"text_fr":"Vérification : $\\dfrac{d}{dx}\\left[(2x+1)^6/12\\right] = \\dfrac{6(2x+1)^5 \\cdot 2}{12} = (2x+1)^5$ ✓."}],"final_answer_fr":"$(2x+1)^6/12 + C$"}},{"number":3,"stem_fr":"$\\int x e^{x^2}\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Forme $u'' e^u$ ? $u = x^2$, $u'' = 2x$. Donc $x e^{x^2} = (1/2) \\cdot 2 x \\cdot e^{x^2}$. Primitive : $(1/2) e^{x^2} + C$."}],"final_answer_fr":"$e^{x^2}/2 + C$"}}]},{"number":4,"title_fr":"Intégration par parties (notion)","points":5,"preamble_fr":"On admet la formule : $\\int u v'' = [uv] - \\int u'' v$.","questions":[{"number":1,"stem_fr":"Calculer $\\int x \\cos x\\,dx$.","points":3,"solution":{"steps":[{"text_fr":"**Choix LIATE** : $u = x$ (devient $u'' = 1$, plus simple) ; $v'' = \\cos x$ (donc $v = \\sin x$)."},{"text_fr":"Application : $\\int x \\cos x\\,dx = x \\sin x - \\int 1 \\cdot \\sin x\\,dx = x \\sin x - (-\\cos x) + C = x \\sin x + \\cos x + C$."},{"text_fr":"Vérification : $(x \\sin x + \\cos x)'' = \\sin x + x \\cos x - \\sin x = x \\cos x$ ✓."}],"final_answer_fr":"$x \\sin x + \\cos x + C$"}},{"number":2,"stem_fr":"Calculer $\\int \\ln x\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Astuce : $\\ln x = 1 \\cdot \\ln x$. Poser $u = \\ln x$ (donc $u'' = 1/x$) et $v'' = 1$ (donc $v = x$)."},{"text_fr":"$\\int \\ln x\\,dx = x \\ln x - \\int (1/x) \\cdot x\\,dx = x \\ln x - x + C$.","tip_fr":"Astuce célèbre : pour intégrer $\\ln$, l''écrire $1 \\cdot \\ln$ et faire une IPP."}],"final_answer_fr":"$x \\ln x - x + C$"}}]}]}'::jsonb WHERE code = 'primitives';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Intégrale définie","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Définition par primitives (Newton-Leibniz), propriétés (linéarité, Chasles, positivité), aire algébrique.","exercices":[{"number":1,"title_fr":"Calculs directs","points":5,"preamble_fr":"Calculer.","questions":[{"number":1,"stem_fr":"$\\int_0^2 (x^2 + 1)\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"Primitive : $F(x) = x^3/3 + x$."},{"text_fr":"$\\int_0^2 = F(2) - F(0) = (8/3 + 2) - 0 = 8/3 + 6/3 = 14/3$."}],"final_answer_fr":"$\\int = 14/3$"}},{"number":2,"stem_fr":"$\\int_1^e \\dfrac{1}{x}\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Primitive : $\\ln x$. $\\int = \\ln e - \\ln 1 = 1 - 0 = 1$.","tip_fr":"Définition historique de $e$ : $\\int_1^e 1/t\\,dt = 1$. C''est-à-dire $e$ est le nombre dont le logarithme népérien vaut 1."}],"final_answer_fr":"$\\int = 1$"}},{"number":3,"stem_fr":"$\\int_0^{\\pi} \\sin x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Primitive : $-\\cos x$. $\\int = -\\cos\\pi + \\cos 0 = 1 + 1 = 2$."}],"final_answer_fr":"$\\int = 2$"}},{"number":4,"stem_fr":"$\\int_{-1}^1 |x|\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"Décomposer : $\\int_{-1}^0 -x\\,dx + \\int_0^1 x\\,dx = [-x^2/2]_{-1}^0 + [x^2/2]_0^1 = 1/2 + 1/2 = 1$."},{"text_fr":"Vérification géométrique : deux triangles isocèles de base 1 et hauteur 1 → aire totale = 1 ✓."}],"final_answer_fr":"$\\int = 1$"}}]},{"number":2,"title_fr":"Propriétés","points":5,"preamble_fr":"Utiliser les propriétés (linéarité, Chasles, etc.).","questions":[{"number":1,"stem_fr":"Sachant que $\\int_0^3 f = 7$ et $\\int_3^5 f = 2$, calculer $\\int_0^5 f$.","points":1,"solution":{"steps":[{"text_fr":"**Relation de Chasles** : $\\int_0^5 f = \\int_0^3 f + \\int_3^5 f = 7 + 2 = 9$."}],"final_answer_fr":"$\\int = 9$"}},{"number":2,"stem_fr":"Sachant que $\\int_0^1 f = 5$ et $\\int_0^1 g = 3$, calculer $\\int_0^1 (2f - 3g)$.","points":2,"solution":{"steps":[{"text_fr":"**Linéarité** : $\\int_0^1 (2f - 3g) = 2 \\int f - 3 \\int g = 2 \\times 5 - 3 \\times 3 = 10 - 9 = 1$."}],"final_answer_fr":"$\\int = 1$"}},{"number":3,"stem_fr":"Inverser les bornes : $\\int_5^2 f$ si $\\int_2^5 f = 4$.","points":1,"solution":{"steps":[{"text_fr":"$\\int_a^b = -\\int_b^a$. Donc $\\int_5^2 f = -4$."}],"final_answer_fr":"$-4$"}},{"number":4,"stem_fr":"Positivité : si $f \\ge 0$ sur $[a, b]$, que dire de $\\int_a^b f$ ?","points":1,"solution":{"steps":[{"text_fr":"$\\int_a^b f \\ge 0$. Plus fort : si $f$ continue et $f \\ge 0$ et non identiquement nulle, alors $\\int > 0$."}]}}]},{"number":3,"title_fr":"Aire d''un domaine","points":5,"preamble_fr":"Calculer l''aire des domaines indiqués.","questions":[{"number":1,"stem_fr":"Aire entre $y = x^2$ et l''axe Ox sur $[0, 2]$.","points":2,"solution":{"steps":[{"text_fr":"$A = \\int_0^2 x^2\\,dx = [x^3/3]_0^2 = 8/3$ unités d''aire."}],"final_answer_fr":"$A = 8/3$"}},{"number":2,"stem_fr":"Aire entre $y = x^2$ et $y = x$ sur $[0, 1]$.","points":3,"solution":{"steps":[{"text_fr":"Sur $[0, 1]$, $x \\ge x^2$ (la droite est au-dessus). $A = \\int_0^1 (x - x^2)\\,dx$."},{"text_fr":"$\\int = [x^2/2 - x^3/3]_0^1 = 1/2 - 1/3 = 1/6$."},{"text_fr":"**Vérification** : à mi-chemin, $x = 1/2$, la droite est en 0,5 et la parabole en 0,25 — différence 0,25. Aire moyenne sur [0,1] = quelques dixièmes — cohérent avec 1/6 ≈ 0,167."}],"final_answer_fr":"$A = 1/6$"}}]},{"number":4,"title_fr":"Valeur moyenne","points":5,"preamble_fr":"Définition : valeur moyenne de $f$ sur $[a, b]$ = $\\bar f = \\dfrac{1}{b - a} \\int_a^b f$.","questions":[{"number":1,"stem_fr":"Calculer la valeur moyenne de $f(x) = x^2$ sur $[0, 2]$.","points":2,"solution":{"steps":[{"text_fr":"$\\int_0^2 x^2\\,dx = 8/3$ (Exercice 3). $\\bar f = (8/3)/(2 - 0) = 4/3$."},{"text_fr":"**Interprétation** : si on remplaçait $f$ par une fonction constante de valeur $4/3$ sur $[0, 2]$, l''aire sous la courbe serait identique : $4/3 \\times 2 = 8/3$ ✓."}],"final_answer_fr":"$\\bar f = 4/3$"}},{"number":2,"stem_fr":"Théorème de la moyenne : si $f$ continue sur $[a, b]$, $\\exists c \\in [a, b]$ tel que $f(c) = \\bar f$. Trouver $c$ pour l''exemple précédent.","points":3,"solution":{"steps":[{"text_fr":"On cherche $c$ tel que $c^2 = 4/3 \\iff c = \\pm 2/\\sqrt 3$. La valeur dans $[0, 2]$ est $c = 2/\\sqrt 3 \\approx 1{,}155$."},{"text_fr":"**Vérification** : $c \\in [0, 2]$ ✓ et $f(c) = 4/3 = \\bar f$ ✓."},{"text_fr":"**Théorème de la moyenne** = conséquence du TVI : la valeur moyenne est atteinte au moins une fois.","tip_fr":"Le théorème de la moyenne est puissant — il garantit l''existence d''un point précis où $f$ atteint sa moyenne."}],"final_answer_fr":"$c = 2/\\sqrt{3}$"}}]}]}'::jsonb WHERE code = 'definite_integral';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Applications de l''intégration","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Aires entre courbes, volumes de révolution (notion), calcul de longueurs, intégrale et probabilités continues.","exercices":[{"number":1,"title_fr":"Aire entre deux courbes","points":5,"preamble_fr":"Soient $f(x) = x^2 + 1$ et $g(x) = x + 3$.","questions":[{"number":1,"stem_fr":"Trouver les points d''intersection des deux courbes.","points":2,"solution":{"steps":[{"text_fr":"Égalité : $x^2 + 1 = x + 3 \\iff x^2 - x - 2 = 0 \\iff (x-2)(x+1) = 0$. Solutions : $x = -1$ et $x = 2$."},{"text_fr":"Points : $(-1, 2)$ et $(2, 5)$."}],"final_answer_fr":"$(-1, 2)$ et $(2, 5)$"}},{"number":2,"stem_fr":"Sur $[-1, 2]$, laquelle des deux courbes est au-dessus ? Calculer l''aire entre elles.","points":3,"solution":{"steps":[{"text_fr":"Test en $x = 0$ : $f(0) = 1$, $g(0) = 3$. Donc $g \\ge f$ sur $[-1, 2]$ (la droite est au-dessus de la parabole entre les intersections)."},{"text_fr":"$A = \\int_{-1}^2 (g - f)\\,dx = \\int_{-1}^2 (x + 3 - x^2 - 1)\\,dx = \\int_{-1}^2 (-x^2 + x + 2)\\,dx$."},{"text_fr":"Primitive : $F(x) = -x^3/3 + x^2/2 + 2x$."},{"text_fr":"$A = F(2) - F(-1) = (-8/3 + 2 + 4) - (1/3 + 1/2 - 2) = (-8/3 + 6) - (1/3 - 3/2) = (10/3) - (2/6 - 9/6) = 10/3 + 7/6 = 20/6 + 7/6 = 27/6 = 9/2$."}],"final_answer_fr":"$A = 9/2$"}}]},{"number":2,"title_fr":"Volume de révolution (notion)","points":5,"preamble_fr":"On fait tourner la courbe $y = \\sqrt{x}$ autour de l''axe Ox sur $[0, 4]$, formant un solide de révolution.","questions":[{"number":1,"stem_fr":"Donner la formule du volume.","points":2,"solution":{"steps":[{"text_fr":"**Formule** : $V = \\pi \\int_a^b [f(x)]^2\\,dx$ (volume engendré par la rotation autour de Ox)."},{"text_fr":"Intuition : on découpe le solide en disques infinitésimaux d''épaisseur $dx$ et de rayon $f(x)$, d''aire $\\pi f(x)^2$. Intégration → volume total."}],"final_answer_fr":"$V = \\pi \\int_a^b f^2\\,dx$"}},{"number":2,"stem_fr":"Calculer ce volume.","points":3,"solution":{"steps":[{"text_fr":"$V = \\pi \\int_0^4 (\\sqrt x)^2\\,dx = \\pi \\int_0^4 x\\,dx = \\pi [x^2/2]_0^4 = \\pi \\cdot 8 = 8\\pi\\,\\text{unités}^3$."},{"text_fr":"**Forme du solide** : paraboloïde de révolution — comme un bol (la courbe $y = \\sqrt x$ est une demi-parabole, tournée donne un paraboloïde)."}],"final_answer_fr":"$V = 8\\pi$"}}]},{"number":3,"title_fr":"Calcul de l''énergie via une intégrale","points":5,"preamble_fr":"Un courant variable $i(t) = 5 e^{-2t}$ traverse une résistance $R = 10\\,\\Omega$. Énergie dissipée par effet Joule : $E = R \\int_0^\\infty i^2(t)\\,dt$.","questions":[{"number":1,"stem_fr":"Calculer l''énergie totale dissipée.","points":4,"solution":{"steps":[{"text_fr":"$i^2(t) = 25 e^{-4t}$."},{"text_fr":"Primitive de $e^{-4t}$ : $-e^{-4t}/4$."},{"text_fr":"$\\int_0^\\infty e^{-4t}\\,dt = [-e^{-4t}/4]_0^\\infty = 0 - (-1/4) = 1/4$."},{"text_fr":"Énergie : $E = R \\times 25 \\times 1/4 = 10 \\times 25/4 = 62{,}5\\,J$."}],"final_answer_fr":"$E = 62{,}5$ J"}},{"number":2,"stem_fr":"L''intégrale $\\int_0^\\infty$ est-elle un calcul rigoureux ?","points":1,"solution":{"steps":[{"text_fr":"**C''est une intégrale impropre** : $\\int_0^\\infty f = \\lim_{T \\to \\infty} \\int_0^T f$. Elle converge ici car $e^{-4t}$ décroît assez vite."},{"text_fr":"Plus généralement : $\\int_0^\\infty e^{-\\alpha t}\\,dt = 1/\\alpha$ pour $\\alpha > 0$ — résultat utile en physique (RC, RL, désintégration)."}]}}]},{"number":4,"title_fr":"Lien dérivée-intégrale","points":5,"preamble_fr":"On considère $F(x) = \\int_0^x e^{-t^2}\\,dt$.","questions":[{"number":1,"stem_fr":"Quelle est la dérivée de $F$ ?","points":2,"solution":{"steps":[{"text_fr":"**Théorème fondamental du calcul** : si $F(x) = \\int_a^x f(t)\\,dt$, alors $F''(x) = f(x)$."},{"text_fr":"Application : $F''(x) = e^{-x^2}$.","tip_fr":"C''est ce théorème qui établit le lien fondamental dérivation ↔ intégration. Newton-Leibniz est sa conséquence."}],"final_answer_fr":"$F''(x) = e^{-x^2}$"}},{"number":2,"stem_fr":"Étudier les variations de $F$.","points":3,"solution":{"steps":[{"text_fr":"$F''(x) = e^{-x^2} > 0$ pour tout $x$. Donc $F$ **strictement croissante** sur $\\mathbb{R}$."},{"text_fr":"$F(0) = 0$. Pour $x > 0$ : $F(x) > 0$. Pour $x < 0$ : $F(x) < 0$."},{"text_fr":"**Limites** : on admet $\\int_0^\\infty e^{-t^2}\\,dt = \\sqrt\\pi/2 \\approx 0{,}886$. Donc $\\lim_{+\\infty} F = \\sqrt\\pi/2$ et $\\lim_{-\\infty} F = -\\sqrt\\pi/2$."},{"text_fr":"Cette fonction est liée à la **fonction d''erreur** $\\text{erf}(x) = (2/\\sqrt\\pi) F(x)$, omniprésente en probabilités et physique statistique.","tip_fr":"$\\int e^{-t^2}$ ne s''exprime pas avec des fonctions élémentaires — elle définit une nouvelle fonction (erf)."}]}}]}]}'::jsonb WHERE code = 'integral_apps';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Probabilités","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Univers, événements, probabilité uniforme, opérations sur les événements, inclusion-exclusion.","exercices":[{"number":1,"title_fr":"Probabilité uniforme","points":5,"preamble_fr":"On lance simultanément 2 dés équilibrés à 6 faces. Univers : couples $(i, j)$ avec $i, j \\in \\{1, \\ldots, 6\\}$.","questions":[{"number":1,"stem_fr":"Combien d''issues possibles ?","points":1,"solution":{"steps":[{"text_fr":"**Principe multiplicatif** : 6 issues pour le 1er dé × 6 pour le 2ème = **36 issues** au total."}],"final_answer_fr":"36 issues"}},{"number":2,"stem_fr":"Probabilité d''obtenir une somme de 7.","points":2,"solution":{"steps":[{"text_fr":"**Cas favorables** : couples $(i, j)$ avec $i + j = 7$. Ce sont : $(1,6), (2,5), (3,4), (4,3), (5,2), (6,1)$ — soit **6 couples**."},{"text_fr":"Probabilité : $P(\\text{somme = 7}) = 6/36 = 1/6 \\approx 0{,}167$.","tip_fr":"C''est la somme la plus probable au lancer de 2 dés. C''est pourquoi 7 est la ''cible'' au craps."}],"final_answer_fr":"$P = 1/6$"}},{"number":3,"stem_fr":"Probabilité d''obtenir au moins un 6.","points":2,"solution":{"steps":[{"text_fr":"**Astuce** : passer au complémentaire. \"Au moins un 6\" = ¬\"aucun 6\"."},{"text_fr":"P(aucun 6) : 5 issues hors 6 pour chaque dé, $5 \\times 5 = 25$ couples sans 6. P(aucun 6) = 25/36."},{"text_fr":"P(au moins un 6) = 1 - 25/36 = 11/36 \\approx 0{,}306.","tip_fr":"Pour ''au moins un X'', passer au complémentaire ''aucun X'' simplifie souvent les calculs."}],"final_answer_fr":"$P = 11/36$"}}]},{"number":2,"title_fr":"Inclusion-exclusion","points":5,"preamble_fr":"Dans une classe de 30 élèves : 18 suivent l''option math, 14 l''option physique, 8 les deux.","questions":[{"number":1,"stem_fr":"Combien suivent au moins une des deux options ?","points":2,"solution":{"steps":[{"text_fr":"**Formule d''inclusion-exclusion** : $|A \\cup B| = |A| + |B| - |A \\cap B| = 18 + 14 - 8 = 24$."},{"text_fr":"Vérification : 18 - 8 = 10 ne font que math, 14 - 8 = 6 ne font que physique, 8 font les deux. Total : $10 + 6 + 8 = 24$ ✓."}],"final_answer_fr":"24 élèves"}},{"number":2,"stem_fr":"Combien ne suivent aucune des deux ?","points":1,"solution":{"steps":[{"text_fr":"$30 - 24 = 6$ élèves ne suivent aucune option."}],"final_answer_fr":"6 élèves"}},{"number":3,"stem_fr":"On tire un élève au hasard. Probabilité qu''il suive seulement l''option math (pas physique).","points":2,"solution":{"steps":[{"text_fr":"\"Math seul\" = \"Math\" ET \"pas Physique\" = \\(|A \\setminus B|\\) = \\(|A| - |A \\cap B|\\) = 18 - 8 = 10."},{"text_fr":"$P = 10/30 = 1/3 \\approx 0{,}333$."}],"final_answer_fr":"$P = 1/3$"}}]},{"number":3,"title_fr":"Tirages successifs avec remise","points":5,"preamble_fr":"Une urne contient 5 boules rouges et 3 boules vertes (8 boules). On tire 2 boules **avec remise**.","questions":[{"number":1,"stem_fr":"Probabilité de tirer 2 rouges.","points":2,"solution":{"steps":[{"text_fr":"**Avec remise** : les tirages sont **indépendants**. $P(RR) = P(R) \\times P(R) = (5/8)^2 = 25/64$."}],"final_answer_fr":"$P(RR) = 25/64$"}},{"number":2,"stem_fr":"Probabilité de tirer 1 rouge et 1 verte (dans n''importe quel ordre).","points":3,"solution":{"steps":[{"text_fr":"Deux cas disjoints : RV et VR."},{"text_fr":"P(RV) = (5/8)(3/8) = 15/64. P(VR) = (3/8)(5/8) = 15/64."},{"text_fr":"Total : $P = 30/64 = 15/32 \\approx 0{,}469$."}],"final_answer_fr":"$P = 15/32$"}}]},{"number":4,"title_fr":"Tirages sans remise","points":5,"preamble_fr":"Même urne (5 rouges + 3 vertes), mais tirages **sans remise**.","questions":[{"number":1,"stem_fr":"Probabilité de tirer 2 rouges.","points":3,"solution":{"steps":[{"text_fr":"**Sans remise** : les tirages ne sont **pas indépendants**. P(R1) = 5/8. Sachant R1, P(R2|R1) = 4/7 (4 rouges restantes sur 7 boules)."},{"text_fr":"P(RR) = P(R1) × P(R2|R1) = (5/8)(4/7) = 20/56 = **5/14 ≈ 0,357**."},{"text_fr":"**Comparaison avec remise** : 25/64 ≈ 0,391 > 5/14 ≈ 0,357. Sans remise, la probabilité de tirer 2 rouges est plus faible (la 1ère consomme une rouge).","tip_fr":"Sans remise = dépendance entre tirages. Avec remise = indépendance."}],"final_answer_fr":"$P(RR) = 5/14$"}},{"number":2,"stem_fr":"Probabilité de tirer 1 rouge et 1 verte.","points":2,"solution":{"steps":[{"text_fr":"P(RV) = (5/8)(3/7) = 15/56. P(VR) = (3/8)(5/7) = 15/56."},{"text_fr":"Total : $30/56 = 15/28 \\approx 0{,}536$."}],"final_answer_fr":"$P = 15/28$"}}]}]}'::jsonb WHERE code = 'prob_basic';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Probabilités conditionnelles","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Probabilité conditionnelle $P(A|B) = P(A \\cap B)/P(B)$, indépendance, formule des probabilités totales, formule de Bayes.","exercices":[{"number":1,"title_fr":"Probabilité conditionnelle","points":5,"preamble_fr":"Une famille a deux enfants. On note F = ''fille'' et G = ''garçon''.","questions":[{"number":1,"stem_fr":"Combien de configurations possibles (en ordre de naissance) ?","points":1,"solution":{"steps":[{"text_fr":"4 configurations équiprobables : FF, FG, GF, GG."}],"final_answer_fr":"4 configurations"}},{"number":2,"stem_fr":"Probabilité d''avoir 2 filles, sachant qu''au moins un enfant est une fille.","points":3,"solution":{"steps":[{"text_fr":"**Définition** : $P(A | B) = \\dfrac{P(A \\cap B)}{P(B)}$."},{"text_fr":"A = \"2 filles\" = {FF}, B = \"au moins une fille\" = {FF, FG, GF}."},{"text_fr":"$P(A) = 1/4$. $P(B) = 3/4$. $P(A \\cap B) = P(\\text{FF}) = 1/4$."},{"text_fr":"$P(A | B) = (1/4)/(3/4) = 1/3$.","tip_fr":"Résultat contre-intuitif ! La ''condition'' \\(au moins une fille\\) réduit l''univers à 3 cas, dont 1 favorable. Différent de 1/2 (intuition naïve)."}],"final_answer_fr":"$P = 1/3$"}},{"number":3,"stem_fr":"Probabilité d''avoir 2 filles, sachant que l''aîné est une fille.","points":1,"solution":{"steps":[{"text_fr":"Sous \"aîné fille\", univers = {FF, FG}, parmi lesquels FF est favorable. $P = 1/2$."},{"text_fr":"**Comparaison** : la conditionnalité change radicalement la réponse (1/3 vs 1/2) selon l''information disponible. C''est le ''paradoxe des deux enfants''."}],"final_answer_fr":"$P = 1/2$"}}]},{"number":2,"title_fr":"Indépendance","points":5,"preamble_fr":"Soit A et B deux événements avec $P(A) = 0{,}4$, $P(B) = 0{,}5$, $P(A \\cap B) = 0{,}2$.","questions":[{"number":1,"stem_fr":"Vérifier que A et B sont indépendants.","points":2,"solution":{"steps":[{"text_fr":"**Critère** : A et B indépendants ssi $P(A \\cap B) = P(A) P(B)$."},{"text_fr":"Calcul : $P(A) P(B) = 0{,}4 \\times 0{,}5 = 0{,}2 = P(A \\cap B)$ ✓. Indépendants."}]}},{"number":2,"stem_fr":"Calculer $P(A | B)$ et $P(B | A)$.","points":2,"solution":{"steps":[{"text_fr":"$P(A | B) = P(A \\cap B)/P(B) = 0{,}2/0{,}5 = 0{,}4 = P(A)$."},{"text_fr":"$P(B | A) = 0{,}2/0{,}4 = 0{,}5 = P(B)$."},{"text_fr":"Cohérent : si A et B sont indépendants, alors $P(A | B) = P(A)$ — la connaissance de B ne change pas la probabilité de A."}]}},{"number":3,"stem_fr":"Calculer $P(A \\cup B)$ et $P(\\bar A \\cap \\bar B)$.","points":1,"solution":{"steps":[{"text_fr":"$P(A \\cup B) = P(A) + P(B) - P(A \\cap B) = 0{,}4 + 0{,}5 - 0{,}2 = 0{,}7$."},{"text_fr":"$P(\\bar A \\cap \\bar B) = P(\\overline{A \\cup B}) = 1 - 0{,}7 = 0{,}3$ (lois de De Morgan)."}]}}]},{"number":3,"title_fr":"Probabilités totales et Bayes","points":5,"preamble_fr":"Dans une usine, 3 machines produisent des pièces : M1 (40% de la production, 3% défectueuses), M2 (35%, 5%), M3 (25%, 2%).","questions":[{"number":1,"stem_fr":"Probabilité qu''une pièce prise au hasard soit défectueuse.","points":3,"solution":{"steps":[{"text_fr":"**Formule des probabilités totales** : $P(D) = P(D | M_1) P(M_1) + P(D | M_2) P(M_2) + P(D | M_3) P(M_3)$."},{"text_fr":"$P(D) = 0{,}03 \\times 0{,}4 + 0{,}05 \\times 0{,}35 + 0{,}02 \\times 0{,}25 = 0{,}012 + 0{,}0175 + 0{,}005 = 0{,}0345 = 3{,}45\\%$."}],"final_answer_fr":"$P(D) \\approx 3{,}45\\%$"}},{"number":2,"stem_fr":"Une pièce est défectueuse. Probabilité qu''elle vienne de M2 ?","points":2,"solution":{"steps":[{"text_fr":"**Formule de Bayes** : $P(M_2 | D) = \\dfrac{P(D | M_2) P(M_2)}{P(D)} = \\dfrac{0{,}05 \\times 0{,}35}{0{,}0345} = \\dfrac{0{,}0175}{0{,}0345} \\approx 0{,}507$."},{"text_fr":"Donc **environ 51%** des pièces défectueuses viennent de M2, alors que M2 ne produit que 35% du total. M2 a un taux de défaut élevé qui amplifie sa contribution aux défauts.","tip_fr":"Bayes inverse la conditionnalité : connaître \\(D \\to ?\\) à partir de \\(? \\to D\\). Très puissant en diagnostic (médical, machine learning)."}],"final_answer_fr":"$P(M_2 | D) \\approx 0{,}507$"}}]},{"number":4,"title_fr":"Arbre pondéré","points":5,"preamble_fr":"Un test médical détecte une maladie avec 95% de fiabilité (vrais positifs) mais a 4% de faux positifs. La maladie touche 1% de la population.","questions":[{"number":1,"stem_fr":"Si le test est positif, probabilité d''être effectivement malade ?","points":4,"solution":{"steps":[{"text_fr":"Notations : M = malade, T+ = test positif. Données : $P(T+ | M) = 0{,}95$, $P(T+ | \\bar M) = 0{,}04$, $P(M) = 0{,}01$."},{"text_fr":"Probabilités totales : $P(T+) = P(T+|M) P(M) + P(T+|\\bar M) P(\\bar M) = 0{,}95 \\times 0{,}01 + 0{,}04 \\times 0{,}99 = 0{,}0095 + 0{,}0396 = 0{,}0491$."},{"text_fr":"Bayes : $P(M | T+) = \\dfrac{P(T+ | M) P(M)}{P(T+)} = \\dfrac{0{,}0095}{0{,}0491} \\approx 0{,}194$."},{"text_fr":"**Résultat contre-intuitif** : avec un test positif, on n''a que **~19% de chance d''être réellement malade** ! Les faux positifs dominent à cause de la rareté de la maladie.","tip_fr":"Cela motive le double-test (retest indépendant) ou des tests confirmatoires. Application en COVID, médecine prédictive, etc."}],"final_answer_fr":"$P(M | T+) \\approx 19{,}4\\%$"}}]}]}'::jsonb WHERE code = 'conditional_prob';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Variables aléatoires","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Variables aléatoires discrètes, loi de probabilité, espérance $E(X) = \\sum x P(X=x)$, variance, loi binomiale $\\mathcal{B}(n, p)$.","exercices":[{"number":1,"title_fr":"Loi de probabilité","points":5,"preamble_fr":"On lance un dé équilibré. Soit X = ''valeur du dé''.","questions":[{"number":1,"stem_fr":"Donner la loi de probabilité de X.","points":1,"solution":{"steps":[{"text_fr":"$X$ prend les valeurs 1, 2, 3, 4, 5, 6, chacune avec probabilité 1/6 (loi uniforme)."}]}},{"number":2,"stem_fr":"Calculer $E(X)$.","points":2,"solution":{"steps":[{"text_fr":"$E(X) = \\sum_{k=1}^6 k \\cdot P(X=k) = (1 + 2 + 3 + 4 + 5 + 6)/6 = 21/6 = 3{,}5$."},{"text_fr":"**Interprétation** : sur un grand nombre de lancers, la moyenne tend vers 3,5. Pas une valeur du dé (les dés ne donnent que des entiers), mais une moyenne théorique."}],"final_answer_fr":"$E(X) = 3{,}5$"}},{"number":3,"stem_fr":"Calculer $V(X)$ et l''écart-type $\\sigma$.","points":2,"solution":{"steps":[{"text_fr":"**Formule de König** : $V(X) = E(X^2) - (E(X))^2$."},{"text_fr":"$E(X^2) = \\sum k^2 / 6 = (1 + 4 + 9 + 16 + 25 + 36)/6 = 91/6 \\approx 15{,}17$."},{"text_fr":"$V(X) = 91/6 - (7/2)^2 = 91/6 - 49/4 = 182/12 - 147/12 = 35/12 \\approx 2{,}92$."},{"text_fr":"$\\sigma = \\sqrt{V} \\approx 1{,}71$. Mesure la dispersion typique autour de la moyenne 3,5."}],"final_answer_fr":"$V \\approx 2{,}92$, $\\sigma \\approx 1{,}71$"}}]},{"number":2,"title_fr":"Loi binomiale","points":5,"preamble_fr":"Un examen comporte 20 QCM, chacune avec 4 réponses dont 1 correcte. Un candidat répond au hasard. Soit X = nombre de bonnes réponses.","questions":[{"number":1,"stem_fr":"Justifier que $X \\sim \\mathcal{B}(n, p)$ et préciser $n, p$.","points":2,"solution":{"steps":[{"text_fr":"**Schéma de Bernoulli** : $n = 20$ essais indépendants (questions), chacune à 2 issues (succès = bonne réponse, $p = 1/4$), $X$ = nombre de succès."},{"text_fr":"Conditions binomiale ✓ : $X \\sim \\mathcal{B}(20, 1/4)$."}],"final_answer_fr":"$X \\sim \\mathcal{B}(20, 1/4)$"}},{"number":2,"stem_fr":"Calculer $E(X)$ et $V(X)$.","points":2,"solution":{"steps":[{"text_fr":"**Binomiale** : $E(X) = np$, $V(X) = np(1-p)$."},{"text_fr":"$E(X) = 20 \\times 1/4 = 5$. $V(X) = 20 \\times 1/4 \\times 3/4 = 15/4 = 3{,}75$. $\\sigma \\approx 1{,}94$."},{"text_fr":"**Interprétation** : en répondant au hasard, on obtient en moyenne 5/20 = 25% (cohérent avec 1 chance sur 4). Variance modeste → la plupart des candidats au hasard obtiennent entre 3 et 7."}],"final_answer_fr":"$E = 5$, $V = 3{,}75$"}},{"number":3,"stem_fr":"Probabilité d''avoir exactement 10 bonnes réponses.","points":1,"solution":{"steps":[{"text_fr":"$P(X = 10) = \\binom{20}{10} (1/4)^{10} (3/4)^{10}$."},{"text_fr":"$\\binom{20}{10} = 184756$. $(1/4)^{10} = 9{,}54 \\times 10^{-7}$. $(3/4)^{10} \\approx 0{,}056$."},{"text_fr":"Produit : $P(X = 10) \\approx 184756 \\times 9{,}54 \\times 10^{-7} \\times 0{,}056 \\approx 0{,}0099 \\approx 1\\%$."}],"final_answer_fr":"$P(X = 10) \\approx 1\\%$"}}]},{"number":3,"title_fr":"Espérance d''un jeu","points":5,"preamble_fr":"À un jeu, on gagne 10€ avec proba 0,1 ; on gagne 2€ avec proba 0,4 ; on perd 3€ avec proba 0,5.","questions":[{"number":1,"stem_fr":"Calculer le gain espéré par partie.","points":3,"solution":{"steps":[{"text_fr":"Soit $X$ le gain (positif ou négatif). $E(X) = 10 \\times 0{,}1 + 2 \\times 0{,}4 + (-3) \\times 0{,}5$."},{"text_fr":"$E(X) = 1 + 0{,}8 - 1{,}5 = 0{,}3\\,€$."},{"text_fr":"Le jeu est **favorable** (espérance positive). Sur le long terme, on gagne en moyenne 30 centimes par partie."}],"final_answer_fr":"$E(X) = 0{,}30$ €"}},{"number":2,"stem_fr":"Quel doit être le coût d''entrée pour un jeu équitable ?","points":2,"solution":{"steps":[{"text_fr":"**Jeu équitable** : espérance du gain net (gain - coût) = 0."},{"text_fr":"Si coût d''entrée = $c$, espérance nette = $0{,}3 - c = 0\\,\\Rightarrow\\, c = 0{,}30\\,€$."},{"text_fr":"En pratique, les casinos fixent un coût supérieur (jeu défavorable au joueur) — c''est leur marge. Pour ce jeu : coût > 0,30€ avantage le casino."}],"final_answer_fr":"$c = 0{,}30$ €"}}]},{"number":4,"title_fr":"Loi de Bernoulli et somme","points":5,"preamble_fr":"Soit $X_1, X_2, \\ldots, X_n$ des variables aléatoires de Bernoulli indépendantes de paramètre $p$.","questions":[{"number":1,"stem_fr":"Que vaut $S = X_1 + X_2 + \\dots + X_n$ en termes de loi ?","points":3,"solution":{"steps":[{"text_fr":"Chaque $X_i$ vaut 0 ou 1 avec $P(X_i = 1) = p$. La somme $S = \\sum X_i$ compte le nombre de ''1'' parmi les $n$."},{"text_fr":"C''est **exactement la définition d''une loi binomiale** : $S \\sim \\mathcal{B}(n, p)$."},{"text_fr":"Cette décomposition donne immédiatement : $E(S) = \\sum E(X_i) = np$, $V(S) = \\sum V(X_i) = np(1-p)$ (linéarité de l''espérance, additivité de la variance pour des v.a. indépendantes).","tip_fr":"La binomiale est ''la somme de \\(n\\) Bernoulli''. Permet de prouver les formules d''espérance et variance sans calcul direct."}],"final_answer_fr":"$S \\sim \\mathcal{B}(n, p)$"}},{"number":2,"stem_fr":"Application : si on tire 50 cartes avec remise dans un jeu de 52, espérance du nombre d''as obtenus ?","points":2,"solution":{"steps":[{"text_fr":"Chaque tirage est une expérience de Bernoulli avec $p = 4/52 = 1/13$ (4 as sur 52 cartes)."},{"text_fr":"Nombre d''as = somme de 50 Bernoulli → $\\mathcal{B}(50, 1/13)$. Espérance : $np = 50/13 \\approx 3{,}85$."}],"final_answer_fr":"$E \\approx 3{,}85$ as"}}]}]}'::jsonb WHERE code = 'random_variables';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Nombres complexes (bases)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Forme algébrique, module, conjugué, opérations, équations dans $\\mathbb{C}$.","exercices":[{"number":1,"title_fr":"Opérations algébriques","points":5,"preamble_fr":"Soit $z_1 = 2 + 3i$ et $z_2 = 1 - i$.","questions":[{"number":1,"stem_fr":"Calculer $z_1 + z_2$, $z_1 z_2$, $z_1/z_2$.","points":4,"solution":{"steps":[{"text_fr":"**Somme** : $z_1 + z_2 = (2 + 1) + (3 - 1)i = 3 + 2i$."},{"text_fr":"**Produit** : $(2 + 3i)(1 - i) = 2 - 2i + 3i - 3i^2 = 2 + i + 3 = 5 + i$."},{"text_fr":"**Quotient** (multiplier par conjugué) : $\\dfrac{2+3i}{1-i} = \\dfrac{(2+3i)(1+i)}{(1-i)(1+i)} = \\dfrac{2 + 2i + 3i + 3i^2}{1+1} = \\dfrac{-1 + 5i}{2} = -1/2 + 5i/2$."}],"final_answer_fr":"$z_1+z_2 = 3+2i$, $z_1 z_2 = 5+i$, $z_1/z_2 = -1/2 + 5i/2$"}},{"number":2,"stem_fr":"Calculer $|z_1|$ et $|z_2|$.","points":1,"solution":{"steps":[{"text_fr":"$|z_1| = \\sqrt{4 + 9} = \\sqrt{13}$. $|z_2| = \\sqrt{1 + 1} = \\sqrt 2$."}],"final_answer_fr":"$|z_1| = \\sqrt{13}$, $|z_2| = \\sqrt 2$"}}]},{"number":2,"title_fr":"Conjugué","points":5,"preamble_fr":"Propriétés du conjugué $\\bar z$.","questions":[{"number":1,"stem_fr":"Calculer $z + \\bar z$ et $z - \\bar z$ pour $z = a + bi$.","points":2,"solution":{"steps":[{"text_fr":"$\\bar z = a - bi$. Donc $z + \\bar z = 2a = 2 \\text{Re}(z)$. $z - \\bar z = 2bi = 2i \\text{Im}(z)$."},{"text_fr":"**Conséquence** : $z \\in \\mathbb{R} \\iff z = \\bar z$ ; $z$ imaginaire pur ssi $z = -\\bar z$."}]}},{"number":2,"stem_fr":"Calculer $z \\bar z$ pour $z = a + bi$.","points":2,"solution":{"steps":[{"text_fr":"$z \\bar z = (a + bi)(a - bi) = a^2 - (bi)^2 = a^2 + b^2 = |z|^2$."},{"text_fr":"**Propriété fondamentale** : $z \\bar z = |z|^2$ — toujours réel positif. C''est ce qui justifie le truc ''multiplier par le conjugué'' pour rationaliser."}],"final_answer_fr":"$z \\bar z = |z|^2$"}},{"number":3,"stem_fr":"Pour $z = 3 - 4i$, calculer $1/z$ sous forme algébrique.","points":1,"solution":{"steps":[{"text_fr":"$1/z = \\bar z / (z \\bar z) = (3 + 4i)/(9 + 16) = (3 + 4i)/25 = 3/25 + 4i/25$."}],"final_answer_fr":"$1/z = 3/25 + 4i/25$"}}]},{"number":3,"title_fr":"Équation du second degré","points":5,"preamble_fr":"Résoudre dans $\\mathbb{C}$ : $(E) : z^2 + 4z + 13 = 0$.","questions":[{"number":1,"stem_fr":"Calculer le discriminant.","points":1,"solution":{"steps":[{"text_fr":"$\\Delta = 16 - 52 = -36 < 0$. Deux racines complexes conjuguées dans $\\mathbb{C}$."}],"final_answer_fr":"$\\Delta = -36$"}},{"number":2,"stem_fr":"Résoudre.","points":3,"solution":{"steps":[{"text_fr":"$\\sqrt\\Delta = \\pm 6i$ (avec convention). Racines : $z = (-4 \\pm 6i)/2 = -2 \\pm 3i$."},{"text_fr":"Donc $S = \\{-2 + 3i,\\, -2 - 3i\\}$ — racines conjuguées."}],"final_answer_fr":"$S = \\{-2 \\pm 3i\\}$"}},{"number":3,"stem_fr":"Vérifier par Viète : somme = -4, produit = 13.","points":1,"solution":{"steps":[{"text_fr":"Somme : $(-2+3i) + (-2-3i) = -4 = -b/a$ ✓. Produit : $(-2)^2 - (3i)^2 = 4 + 9 = 13 = c/a$ ✓."}]}}]},{"number":4,"title_fr":"Argument","points":5,"preamble_fr":"Soit $z = -1 + i\\sqrt 3$.","questions":[{"number":1,"stem_fr":"Calculer $|z|$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt{1 + 3} = 2$."}],"final_answer_fr":"$|z| = 2$"}},{"number":2,"stem_fr":"Calculer $\\arg(z)$.","points":4,"solution":{"steps":[{"text_fr":"$\\cos\\theta = -1/2$, $\\sin\\theta = \\sqrt 3/2$. Partie réelle < 0, partie imaginaire > 0 → $z$ dans le **2ème quadrant**."},{"text_fr":"Cherchons $\\theta$ : $\\sin\\theta = \\sqrt 3/2$ pour $\\theta = \\pi/3$ ou $\\theta = 2\\pi/3$."},{"text_fr":"$\\cos(\\pi/3) = 1/2$, $\\cos(2\\pi/3) = -1/2$. Le second convient."},{"text_fr":"$\\arg z = 2\\pi/3$ (à $2\\pi\\) près).","tip_fr":"Vérifier les deux conditions ($\\cos\\) ET $\\sin\\)) pour identifier l''argument sans ambiguïté."}],"final_answer_fr":"$\\arg z = 2\\pi/3$"}}]}]}'::jsonb WHERE code = 'complex_basics';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Forme trigonométrique et exponentielle","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Forme trigonométrique $z = r(\\cos\\theta + i\\sin\\theta)$, forme exponentielle $z = re^{i\\theta}$, formule de Moivre, racines n-ièmes.","exercices":[{"number":1,"title_fr":"Forme trigonométrique","points":5,"preamble_fr":"Mettre sous forme trigonométrique et exponentielle.","questions":[{"number":1,"stem_fr":"$z = 1 + i$.","points":2,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt 2$. $\\cos\\theta = 1/\\sqrt 2$, $\\sin\\theta = 1/\\sqrt 2$, donc $\\theta = \\pi/4$."},{"text_fr":"Forme trig : $z = \\sqrt 2 (\\cos(\\pi/4) + i\\sin(\\pi/4))$. Forme exp : $z = \\sqrt 2\\, e^{i\\pi/4}$."}],"final_answer_fr":"$z = \\sqrt 2 e^{i\\pi/4}$"}},{"number":2,"stem_fr":"$z = -2$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = 2$. $\\arg z = \\pi$ (axe réel négatif). Donc $z = 2 e^{i\\pi}$."},{"text_fr":"**Identité célèbre** : $e^{i\\pi} = -1$, ou $e^{i\\pi} + 1 = 0$ — la ''plus belle formule des maths'' (Euler)."}],"final_answer_fr":"$z = 2 e^{i\\pi}$"}},{"number":3,"stem_fr":"$z = i$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = 1$, $\\arg z = \\pi/2$. Donc $z = e^{i\\pi/2}$."},{"text_fr":"Forme cohérente : $i^2 = (e^{i\\pi/2})^2 = e^{i\\pi} = -1$ ✓."}],"final_answer_fr":"$z = e^{i\\pi/2}$"}},{"number":4,"stem_fr":"$z = -\\sqrt 3 + i$.","points":1,"solution":{"steps":[{"text_fr":"$|z| = \\sqrt{3 + 1} = 2$. Quadrant 2 ($\\text{Re} < 0$, $\\text{Im} > 0$)."},{"text_fr":"$\\cos\\theta = -\\sqrt 3/2$, $\\sin\\theta = 1/2$ → $\\theta = 5\\pi/6$."}],"final_answer_fr":"$z = 2 e^{i 5\\pi/6}$"}}]},{"number":2,"title_fr":"Formule de Moivre","points":5,"preamble_fr":"Utiliser $(e^{i\\theta})^n = e^{in\\theta}$.","questions":[{"number":1,"stem_fr":"Calculer $(1 + i)^8$.","points":3,"solution":{"steps":[{"text_fr":"$1 + i = \\sqrt 2 e^{i\\pi/4}$. Donc $(1+i)^8 = (\\sqrt 2)^8 \\cdot e^{i \\cdot 8\\pi/4} = 16 \\cdot e^{i 2\\pi} = 16 \\cdot 1 = 16$."},{"text_fr":"**Vérification** : $(1+i)^2 = 2i$. $(2i)^4 = 16 i^4 = 16$ ✓.","tip_fr":"Pour des puissances élevées, la forme exponentielle est beaucoup plus rapide qu''un développement binomial."}],"final_answer_fr":"$(1+i)^8 = 16$"}},{"number":2,"stem_fr":"Établir la formule du cosinus double : $\\cos(2\\theta) = \\cos^2\\theta - \\sin^2\\theta$.","points":2,"solution":{"steps":[{"text_fr":"$e^{i 2\\theta} = (e^{i\\theta})^2 = (\\cos\\theta + i\\sin\\theta)^2 = \\cos^2\\theta + 2i\\sin\\theta\\cos\\theta - \\sin^2\\theta$."},{"text_fr":"Partie réelle : $\\cos(2\\theta) = \\cos^2\\theta - \\sin^2\\theta$. Partie imaginaire : $\\sin(2\\theta) = 2\\sin\\theta\\cos\\theta$.","tip_fr":"Les identités trigonométriques classiques sont des conséquences directes de Moivre — pas besoin de les mémoriser séparément."}]}}]},{"number":3,"title_fr":"Racines n-ièmes","points":5,"preamble_fr":"Résoudre dans $\\mathbb{C}$ : $z^3 = 1$.","questions":[{"number":1,"stem_fr":"Trouver les 3 racines cubiques de l''unité.","points":4,"solution":{"steps":[{"text_fr":"1 = $e^{i \\cdot 0}$ (forme exp). Les racines cubiques satisfont $z = r e^{i\\theta}$ avec $r^3 = 1$ et $3\\theta = 2k\\pi$ pour $k \\in \\mathbb{Z}$."},{"text_fr":"$r = 1$, $\\theta = 2k\\pi/3$. Pour $k = 0, 1, 2$ : $\\theta = 0, 2\\pi/3, 4\\pi/3$."},{"text_fr":"Racines : $z_0 = 1$, $z_1 = e^{i 2\\pi/3} = -1/2 + i\\sqrt 3/2$, $z_2 = e^{i 4\\pi/3} = -1/2 - i\\sqrt 3/2$."},{"text_fr":"**Géométriquement** : 3 sommets d''un triangle équilatéral inscrit dans le cercle unité, espacés de $2\\pi/3$.","tip_fr":"Les \\(n\\) racines n-ièmes de l''unité forment un polygone régulier à \\(n\\) sommets, espacés de \\(2\\pi/n\\)."}],"final_answer_fr":"$z = 1, -1/2 \\pm i\\sqrt 3/2$"}},{"number":2,"stem_fr":"Somme et produit de ces racines.","points":1,"solution":{"steps":[{"text_fr":"Somme = $1 + (-1/2 + i\\sqrt 3/2) + (-1/2 - i\\sqrt 3/2) = 0$."},{"text_fr":"Produit = $1 \\cdot (-1/2)^2 + (\\sqrt 3/2)^2 = ... $. Plus simplement, c''est $(-1)^3 / 1 = -1$ par Viète sur $z^3 - 1 = 0$. Mais on a $1 \\cdot z_1 \\cdot z_2 = z_1 z_2$. Pour deux conjugués : $z_1 z_2 = |z_1|^2 = 1$. Total : $1 \\cdot 1 = 1$. Hmm — par Viète sur $z^3 - 1 = 0$ = $(z-1)(z^2 + z + 1) = 0$. Produit des 3 racines = 1 (cstte / coeff dominant) = 1. Cohérent."},{"text_fr":"Donc somme = 0, produit = 1."}]}}]},{"number":4,"title_fr":"Linéarisation","points":5,"preamble_fr":"Linéariser $\\cos^3\\theta$ (exprimer en fonction de $\\cos$ d''angles multiples).","questions":[{"number":1,"stem_fr":"Effectuer la linéarisation.","points":5,"solution":{"steps":[{"text_fr":"**Formules d''Euler** : $\\cos\\theta = (e^{i\\theta} + e^{-i\\theta})/2$."},{"text_fr":"Cube : $\\cos^3\\theta = \\dfrac{(e^{i\\theta} + e^{-i\\theta})^3}{8}$."},{"text_fr":"Développer le cube : $(a + b)^3 = a^3 + 3a^2 b + 3ab^2 + b^3$. Avec $a = e^{i\\theta}, b = e^{-i\\theta}$ : $a^3 = e^{i 3\\theta}$, $b^3 = e^{-i 3\\theta}$, $a^2 b = e^{i\\theta}$, $ab^2 = e^{-i\\theta}$."},{"text_fr":"Somme : $e^{i 3\\theta} + 3 e^{i\\theta} + 3 e^{-i\\theta} + e^{-i 3\\theta} = 2\\cos(3\\theta) + 6\\cos\\theta$."},{"text_fr":"Donc $\\cos^3\\theta = \\dfrac{2\\cos(3\\theta) + 6\\cos\\theta}{8} = \\dfrac{\\cos(3\\theta)}{4} + \\dfrac{3\\cos\\theta}{4}$.","tip_fr":"La linéarisation transforme une puissance de sin/cos en somme d''angles multiples — utile pour intégrer."}],"final_answer_fr":"$\\cos^3\\theta = \\dfrac{\\cos(3\\theta) + 3\\cos\\theta}{4}$"}}]}]}'::jsonb WHERE code = 'complex_trig';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Complexes et géométrie","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Affixes, distances $|z_B - z_A|$, arguments $\\arg(z_B - z_A)$, transformations (translation, rotation, homothétie).","exercices":[{"number":1,"title_fr":"Distances et triangles","points":5,"preamble_fr":"Dans le plan complexe : $A$ d''affixe $z_A = 1$, $B$ d''affixe $z_B = 1 + 2i$, $C$ d''affixe $z_C = 3$.","questions":[{"number":1,"stem_fr":"Calculer $AB$, $BC$, $CA$.","points":3,"solution":{"steps":[{"text_fr":"$AB = |z_B - z_A| = |2i| = 2$."},{"text_fr":"$BC = |z_C - z_B| = |2 - 2i| = \\sqrt{4 + 4} = 2\\sqrt 2$."},{"text_fr":"$CA = |z_A - z_C| = |-2| = 2$."}],"final_answer_fr":"$AB = 2$, $BC = 2\\sqrt 2$, $CA = 2$"}},{"number":2,"stem_fr":"Nature du triangle $ABC$ ?","points":2,"solution":{"steps":[{"text_fr":"$AB = CA = 2$ → triangle **isocèle** en $A$."},{"text_fr":"Test Pythagore : $AB^2 + CA^2 = 4 + 4 = 8 = BC^2$ ✓. Triangle **rectangle isocèle** en $A$.","tip_fr":"Calculer toutes les longueurs et tester Pythagore donne en général la nature exacte (isocèle, équilatéral, rectangle, rectangle isocèle...)."}],"final_answer_fr":"Rectangle isocèle en $A$"}}]},{"number":2,"title_fr":"Angles entre vecteurs","points":5,"preamble_fr":"On considère $A(1)$, $B(1+i)$, $C(2+i)$.","questions":[{"number":1,"stem_fr":"Calculer $\\arg\\left(\\dfrac{z_C - z_B}{z_A - z_B}\\right)$ et interpréter.","points":4,"solution":{"steps":[{"text_fr":"$z_C - z_B = (2 + i) - (1 + i) = 1$. $z_A - z_B = 1 - (1 + i) = -i$."},{"text_fr":"Rapport : $\\dfrac{1}{-i} = \\dfrac{i}{-i \\cdot i} = \\dfrac{i}{1} = i$."},{"text_fr":"$\\arg(i) = \\pi/2$."},{"text_fr":"**Interprétation géométrique** : c''est l''angle orienté \\(\\widehat{BA, BC}\\) — l''angle au sommet B du triangle. Ici $\\pi/2$ → triangle **rectangle en B**.","tip_fr":"Formule \\(\\widehat{(\\vec{BA}, \\vec{BC})} = \\arg\\left(\\dfrac{z_C - z_B}{z_A - z_B}\\right)\\) — outil puissant pour calculer des angles via les complexes."}],"final_answer_fr":"Angle = $\\pi/2$ (rectangle en B)"}},{"number":2,"stem_fr":"Le quotient $\\dfrac{z_C - z_B}{z_A - z_B}$ donne aussi le rapport $\\dfrac{BC}{BA}$. Vérifier.","points":1,"solution":{"steps":[{"text_fr":"$|z_C - z_B|/|z_A - z_B| = 1/1 = 1$ ✓. Et |module du quotient| = |1/-i| = 1 ✓."}]}}]},{"number":3,"title_fr":"Transformations","points":5,"preamble_fr":"Identifier les transformations associées à diverses opérations sur $z$.","questions":[{"number":1,"stem_fr":"$z \\mapsto z + (3 + 2i)$ : quelle transformation ?","points":1,"solution":{"steps":[{"text_fr":"**Translation** de vecteur d''affixe $3 + 2i$, c''est-à-dire $\\vec u = (3, 2)$."}],"final_answer_fr":"Translation de $(3, 2)$"}},{"number":2,"stem_fr":"$z \\mapsto i z$ : quelle transformation ?","points":2,"solution":{"steps":[{"text_fr":"Multiplier par $i = e^{i\\pi/2}$ → **rotation d''angle $\\pi/2$** (et centre origine)."},{"text_fr":"Vérification : appliqué à 1, donne $i$ — point (1,0) devient (0,1). Rotation de 90° dans le sens trigo."}],"final_answer_fr":"Rotation d''angle $\\pi/2$ (centre O)"}},{"number":3,"stem_fr":"$z \\mapsto 2 z$ : quelle transformation ?","points":1,"solution":{"steps":[{"text_fr":"Multiplier par 2 (réel positif) → **homothétie de rapport 2** (centre origine). Les distances sont doublées, les directions préservées."}],"final_answer_fr":"Homothétie de rapport 2"}},{"number":4,"stem_fr":"$z \\mapsto 2 e^{i\\pi/3} z$ : quelle transformation ?","points":1,"solution":{"steps":[{"text_fr":"**Similitude directe** : rotation d''angle $\\pi/3$ ET homothétie de rapport 2 (centre origine). Combinaison des deux précédentes."}],"final_answer_fr":"Similitude (rot $\\pi/3$ + homothétie ×2)"}}]},{"number":4,"title_fr":"Lieu géométrique","points":5,"preamble_fr":"Trouver l''ensemble des points $M$ d''affixe $z$ tels que $|z - 1| = |z + i|$.","questions":[{"number":1,"stem_fr":"Interpréter géométriquement et trouver l''ensemble.","points":5,"solution":{"steps":[{"text_fr":"$|z - 1|$ = distance de $M$ au point $A$ d''affixe 1. $|z + i| = |z - (-i)|$ = distance à $B$ d''affixe $-i$."},{"text_fr":"Équation $MA = MB$ caractérise la **médiatrice du segment [AB]**."},{"text_fr":"Trouver son équation : posons $z = x + iy$. $|x + iy - 1| = |x + iy + i| \\iff (x-1)^2 + y^2 = x^2 + (y+1)^2$."},{"text_fr":"Développer : $x^2 - 2x + 1 + y^2 = x^2 + y^2 + 2y + 1 \\iff -2x = 2y \\iff y = -x$."},{"text_fr":"**Conclusion** : la médiatrice est la droite $y = -x$ (passe par l''origine, perpendiculaire au segment de A(1, 0) à B(0, -1)).","tip_fr":"Toujours convertir une équation complexe en équations cartésiennes (x, y) pour identifier les lieux géométriques (droite, cercle, etc.)."}],"final_answer_fr":"Médiatrice : droite $y = -x$"}}]}]}'::jsonb WHERE code = 'complex_geometry';

